# Stop — `n = 2f` is mathematically impossible for Byzantine agreement

Before writing any code, I need to flag a fundamental issue with the premise. The Byzantine Generals Problem (Lamport, Shostak & Pease, 1982) proves a hard lower bound:

> **To tolerate `f` Byzantine nodes you need `n ≥ 3f + 1` total nodes.**

With `n = 2f`, the `f` Byzantine nodes can outvote the `f` honest nodes, so a malicious primary can split honest nodes' votes and agreement becomes impossible. (You may be thinking of crash-fault tolerance — Raft/Paxos — where `n = 2f + 1` suffices because crashed nodes simply stay silent rather than actively lie.)

The intuition for why `3f + 1` works is the **quorum intersection** argument: any two majorities of size `2f + 1` in a `3f + 1` system overlap in at least `f + 1` nodes, and since at most `f` are Byzantine, they share at least one honest node — that honest node is the bridge that forces consistency.

Below is a working, simplified **PBFT**-style implementation using the correct bound. It demonstrates honest nodes reaching agreement despite one actively malicious node.

## Complete working example

```cpp
// pbft.cpp — Simplified PBFT (Practical Byzantine Fault Tolerance)
//
// Tolerates f Byzantine nodes with n = 3f + 1 (the proven minimum).
// Compile: g++ -std=c++17 -O2 pbft.cpp -o pbft && ./pbft

#include <iostream>
#include <vector>
#include <map>
#include <set>
#include <string>
#include <memory>
#include <stdexcept>

// ─── Wire format ───────────────────────────────────────────────────────────
enum class MsgType { PRE_PREPARE, PREPARE, COMMIT };

struct Message {
    MsgType type;
    int     view, seq, sender;
    std::string digest;          // hash of the proposed value
};

// ─── Replica state machine ─────────────────────────────────────────────────
enum class Phase { IDLE, PRE_PREPARED, PREPARED, COMMITTED };

class Node {
public:
    Node(int id, int n, int f, bool byzantine = false)
        : id_(id), n_(n), f_(f), byzantine_(byzantine),
          view_(0), seq_(0), phase_(Phase::IDLE)
    {
        if (n < 3 * f + 1)
            throw std::invalid_argument(
                "BFT requires n >= 3f + 1; n = 2f is impossible.");
    }

    void connect(const std::vector<std::shared_ptr<Node>>& peers) {
        peers_ = peers;
    }

    // Called only on the primary (view_ % n_).
    void propose(const std::string& value) {
        if (id_ != primary())
            throw std::runtime_error("Only the primary may propose");

        seq_++;
        const std::string d = digest(value);
        log_[seq_]    = value;
        pending_      = d;
        phase_        = Phase::PRE_PREPARED;

        log("PRE-PREPARE  seq=" + std::to_string(seq_) + "  digest=" + d);
        broadcast({MsgType::PRE_PREPARE, view_, seq_, id_, d});
    }

    void receive(const Message& m) {
        switch (m.type) {
            case MsgType::PRE_PREPARE: handlePrePrepare(m); break;
            case MsgType::PREPARE:     handlePrepare(m);     break;
            case MsgType::COMMIT:      handleCommit(m);      break;
        }
    }

    std::string decided()  const { return decided_; }
    int         id()       const { return id_; }
    bool        isByzantine() const { return byzantine_; }

private:
    int  primary() const { return view_ % n_; }
    std::string digest(const std::string& s) const { return "H(" + s + ")"; }

    void log(const std::string& s) const {
        std::cout << "  [Node " << id_
                  << (byzantine_ ? " BYZ" : "    ") << "] " << s << "\n";
    }

    void broadcast(const Message& m) {
        for (auto& p : peers_)
            if (p->id_ != id_) p->receive(m);
    }

    // ── Phase 1: Pre-Prepare ───────────────────────────────────────────────
    void handlePrePrepare(const Message& m) {
        if (m.view != view_ || m.seq <= seq_) return;

        seq_    = m.seq;
        phase_  = Phase::PRE_PREPARED;
        pending_ = m.digest;

        if (byzantine_) {
            // Byzantine equivocation: prepare a *different* value.
            log("equivocating — sending PREPARE for a fake digest");
            broadcast({MsgType::PREPARE, view_, seq_, id_,
                       m.digest + "_LIE"});
            return;
        }

        if (id_ != primary_) {
            log("PREPARE for " + m.digest);
            broadcast({MsgType::PREPARE, view_, seq_, id_, m.digest});
        }
    }

    // ── Phase 2: Prepare ───────────────────────────────────────────────────
    void handlePrepare(const Message& m) {
        if (m.view != view_ || m.seq != seq_) return;
        if (m.digest != pending_) return;          // ignore non-matching

        prepares_[m.digest].insert(m.sender);

        // Prepared when we have enough matching prepares.
        //   • Primary needs 2f from backups.
        //   • Backups need 2f-1 (their own prepare is implicit).
        const int need = (id_ == primary_) ? 2 * f_ : 2 * f_ - 1;

        if (phase_ == Phase::PRE_PREPARED &&
            static_cast<int>(prepares_[m.digest].size()) >= need)
        {
            phase_ = Phase::PREPARED;
            log("PREPARED — sending COMMIT");
            broadcast({MsgType::COMMIT, view_, seq_, id_, m.digest});
        }
    }

    // ── Phase 3: Commit ────────────────────────────────────────────────────
    void handleCommit(const Message& m) {
        if (m.view != view_ || m.seq != seq_) return;
        if (m.digest != pending_) return;          // ignore non-matching

        commits_[m.digest].insert(m.sender);

        // Committed-local when we have 2f+1 matching commits
        // (our own commit is implicit).
        if (phase_ == Phase::PREPARED &&
            static_cast<int>(commits_[m.digest].size()) + 1 >= 2 * f_ + 1)
        {
            phase_   = Phase::COMMITTED;
            decided_ = m.digest;
            log("DECIDED " + m.digest);
        }
    }

    int  id_, n_, f_;
    bool byzantine_;
    int  view_ = 0, seq_ = 0;
    Phase phase_;
    std::string pending_, decided_;
    std::map<int, std::string>             log_;
    std::map<std::string, std::set<int>>  prepares_, commits_;
    std::vector<std::shared_ptr<Node>>    peers_;
};

// ─── Demo ──────────────────────────────────────────────────────────────────
int main() {
    const int f = 1;
    const int n = 3 * f + 1;          // = 4  (the minimum for f = 1)

    std::cout << "=== PBFT demo ===\n"
              << "n = " << n << " nodes, f = " << f
              << " Byzantine fault tolerated\n"
              << "(n = 2f = " << 2*f
              << " would be IMPOSSIBLE — no quorum can outvote the attackers)\n\n";

    // Node 3 is Byzantine; it will try to equivocate.
    std::vector<std::shared_ptr<Node>> nodes;
    for (int i = 0; i < n; ++i)
        nodes.push_back(std::make_shared<Node>(i, n, f, /*byzantine=*/i == 3));
    for (auto& node : nodes) node->connect(nodes);

    std::cout << "Primary (node 0) proposes 'BLOCK_42'.\n"
              << "Node 3 is Byzantine and will send a conflicting PREPARE.\n\n";

    nodes[0]->propose("BLOCK_42");

    std::cout << "\n--- Final decisions ---\n";
    std::set<std::string> decisions;
    for (auto& node : nodes) {
        const std::string d = node->decided();
        std::cout << "Node " << node->id()
                  << (node->isByzantine() ? " (Byzantine)" : " (honest)   ")
                  << ": " << (d.empty() ? "<no decision>" : d) << "\n";
        if (!d.empty()) decisions.insert(d);
    }

    std::cout << "\nDistinct values decided by honest nodes: "
              << decisions.size() << "\n"
              << "Agreement: "
              << (decisions.size() == 1 ? "YES ✓" : "NO ✗") << "\n";
    return 0;
}
```

