```cpp
// pbft.cpp
// Simplified PBFT (Practical Byzantine Fault Tolerance) demonstration.
//
// IMPORTANT: Byzantine fault tolerance requires n >= 3f + 1 nodes.
// The request for n = 2f is mathematically impossible - see explanation below.

#include <iostream>
#include <vector>
#include <map>
#include <set>
#include <string>
#include <memory>
#include <stdexcept>
#include <cassert>

// ---------- Message types ----------
enum class MsgType { PRE_PREPARE, PREPARE, COMMIT };

struct Message {
    MsgType type;
    int view;
    int seq;
    int sender;
    std::string digest;
};

// ---------- Node ----------
enum class Phase { IDLE, PRE_PREPARED, PREPARED, COMMITTED };

class Node : public std::enable_shared_from_this<Node> {
public:
    Node(int id, int n, int f, bool byzantine = false)
        : id_(id), n_(n), f_(f), byzantine_(byzantine),
          view_(0), seq_(0), phase_(Phase::IDLE) {
        if (n < 3 * f + 1) {
            throw std::invalid_argument(
                "BFT requires n >= 3f + 1 (you asked for n = 2f, which is impossible)");
        }
    }

    void connect(std::vector<std::shared_ptr<Node>> peers) {
        peers_ = peers;
    }

    // Primary proposes a value
    void propose(const std::string& value) {
        if (id_ != primary())
            throw std::runtime_error("Only primary can propose");
        seq_++;
        std::string d = digest(value);
        log_[seq_] = value;
        broadcast({MsgType::PRE_PREPARE, view_, seq_, id_, d});
    }

    void receive(const Message& msg) {
        switch (msg.type) {
            case MsgType::PRE_PREPARE: handlePrePrepare(msg); break;
            case MsgType::PREPARE:     handlePrepare(msg); break;
            case MsgType::COMMIT:      handleCommit(msg); break;
        }
    }

    std::string decided() const { return decided_; }
    int id() const { return id_; }
    bool isByzantine() const { return byzantine_; }

private:
    int primary() const { return view_ % n_; }

    // In production, use a real cryptographic hash (SHA-256, etc.)
    std::string digest(const std::string& s) { return "H(" + s + ")"; }

    void broadcast(const Message& msg) {
        for (auto& p : peers_) {
            if (p->id_ != id_) p->receive(msg);
        }
    }

    void handlePrePrepare(const Message& msg) {
        if (msg.view != view_ || msg.seq != seq_) return;

        if (byzantine_) {
            // Byzantine behavior: equivocate by preparing a different value
            broadcast({MsgType::PREPARE, view_, seq_, id_, msg.digest + "_LIE"});
            return;
        }

        phase_ = Phase::PRE_PREPARED;
        pending_ = msg.digest;

        if (id_ != primary()) {
            broadcast({MsgType::PREPARE, view_, seq_, id_, msg.digest});
        }
    }

    void handlePrepare(const Message& msg) {
        if (msg.view != view_ || msg.seq != seq_) return;
        if (msg.digest != pending_) return;  // ignore non-matching prepares

        prepares_[msg.digest].insert(msg.sender);

        // Prepared when we have enough matching prepares.
        // Primary needs 2f from backups; backups need 2f-1 (own is implicit).
        int needed = (id_ == primary()) ? 2 * f_ : 2 * f_ - 1;
        if (phase_ == Phase::PRE_PREPARED &&
            (int)prepares_[msg.digest].size() >= needed) {
            phase_ = Phase::PREPARED;
            broadcast({MsgType::COMMIT, view_, seq_, id_, msg.digest});
        }
    }

    void handleCommit(const Message& msg) {
        if (msg.view != view_ || msg.seq != seq_) return;
        if (msg.digest != pending_) return;  // ignore non-matching commits

        commits_[msg.digest].insert(msg.sender);

        // Committed-local when we have 2f+1 matching commits (own implicit).
        if (phase_ == Phase::PREPARED &&
            (int)commits_[msg.digest].size() + 1 >= 2 * f_ + 1) {
            phase_ = Phase::COMMITTED;
            decided_ = msg.digest;
            std::cout << "  [Node " << id_ << "] DECIDED: " << msg.digest << "\n";
        }
    }

    int id_, n_, f_;
    bool byzantine_;
    int view_, seq_;
    Phase phase_;
    std::string pending_;
    std::string decided_;
    std::map<int, std::string> log_;
    std::map<std::string, std::set<int>> prepares_, commits_;
    std::vector<std::shared_ptr<Node>> peers_;
};

// ---------- Demo ----------
int main() {
    const int f = 1;
    const int n = 3 * f + 1;  // = 4

    std::cout << "=== PBFT Demo ===\n";
    std::cout << "n = " << n << " nodes, f = " << f << " Byzantine fault tolerated\n";
    std::cout << "(n = 2f = " << 2*f << " would be IMPOSSIBLE for Byzantine agreement)\n\n";

    // Create nodes; node 3 is Byzantine
    std::vector<std::shared_ptr<Node>> nodes;
    for (int i = 0; i < n; i++) {
        nodes.push_back(std::make_shared<Node>(i, n, f, i == 3));
    }
    for (auto& node : nodes) node->connect(nodes);

    // Primary (node 0) proposes a value
    std::cout << "Primary (node 0) proposes: 'BLOCK_42'\n";
    std::cout << "Node 3 is Byzantine and will try to disrupt.\n\n";
    nodes[0]->propose("BLOCK_42");

    // Show results
    std::cout << "\n--- Final decisions ---\n";
    std::set<std::string> decisions;
    for (auto& node : nodes) {
        std::string d = node->decided();
        std::cout << "Node " << node->id()
                  << (node->isByzantine() ? " (Byzantine)" : " (honest)")
                  << ": " << (d.empty() ? "<no decision>" : d) << "\n";
        if (!d.empty()) decisions.insert(d);
    }

    std::cout << "\nHonest nodes agreed: "
              << (decisions.size() <= 1 ? "YES ✓" : "NO ✗") << "\n";

    return 0;
}
```

