fn parse_lit<F: FnOnce() -> Json>(s: &[u8], lit: &[u8], f: F) -> Result<(Json, &[u8]), Error> {
    if s.len() >= lit.len() && &s[..lit.len()] == lit {
        Ok((f(), &s[lit.len()..]))
    } else {
        Err(Error::UnexpectedByte(s.first().copied().unwrap_or(0)))
    }
}

fn parse_string(s: &[u8]) -> Result<(String, &[u8]), Error> {
    if s.first() != Some(&b'"') {
        return Err(Error::UnexpectedByte(s.first().copied().unwrap_or(0)));
    }
    let mut out = String::new();
    let mut i = 1;
    while i < s.len() {
        let c = s[i];
        if c == b'"' {
            return Ok((out, &s[i+1..]));
        } else if c == b'\\' {
            if i + 1 >= s.len() { return Err(Error::UnexpectedEnd); }
            match s[i+1] {
                b'"' => out.push('"'), b'\\' => out.push('\\'),
                b'/' => out.push('/'), b'b' => out.push('\x08'),
                b'f' => out.push('\x0c'), b'n' => out.push('\n'),
                b'r' => out.push('\r'), b't' => out.push('\t'),
