                    let hex = std::str::from_utf8(&s[i+2..i+6])
                        .map_err(|_| Error::InvalidEscape)?;
                    let code = u32::from_str_radix(hex, 16)
                        .map_err(|_| Error::InvalidEscape)?;
                    let ch = char::from_u32(code).ok_or(Error::InvalidEscape)?;
                    out.push(ch);
                    i += 4;
                }
                _ => return Err(Error::InvalidEscape),
            }
            i += 2;
        } else {
