class KDTree {
    std::unique_ptr<KDNode> root_;

    std::unique_ptr<KDNode> build(std::vector<Point>& points, std::vector<int>& indices, int depth) {
        if (points.empty()) return nullptr;
        int d = points[0].size();
        int axis = depth % d;

        // Sort by axis
        std::sort(indices.begin(), indices.end(), [&](int a, int b) {
            return points[a][axis] < points[b][axis];
        });

        int mid = indices.size() / 2;
        auto node = std::make_unique<KDNode>(points[indices[mid]], indices[mid], axis);

        std::vector<int> left_idx(indices.begin(), indices.begin() + mid);
        std::vector<int> right_idx(indices.begin() + mid + 1, indices.end());

        node->left = build(points, left_idx, depth + 1);
        node->right = build(points, right_idx, depth + 1);

        return node;
    }

    void nearest(const KDNode* node, const Point& target, int& best_idx, double& best_dist) const {
        if (!node) return;

        double d = dist2(target, node->point);
        if (d < best_dist) {
            best_dist = d;
            best_idx = node->index;
        }

        int axis = node->dim;
        double diff = target[axis] - node->point[axis];

        const KDNode* first = diff < 0 ? node->left.get() : node->right.get();
        const KDNode* second = diff < 0 ? node->right.get() : node->left.get();

        nearest(first, target, best_idx, best_dist);

        if (diff * diff < best_dist) {
            nearest(second, target, best_idx, best_dist);
        }
    }

public:
    KDTree(const std::vector<Point>& points) {
        std::vector<Point> pts = points;
        std::vector<int> indices(points.size());
        for (size_t i = 0; i < indices.size(); ++i) indices[i] = i;
        root_ = build(pts, indices, 0);
    }

    int nearest(const Point& target) const {
        int best_idx = -1;
        double best_dist = std::numeric_limits<double>::infinity();
        nearest(root_.get(), target, best_idx, best_dist);
        return best_idx;
    }
};
