# The Honest Answer

**True immunity to SQL injection without changing queries is impossible.** Once user input is concatenated into a SQL string, it becomes indistinguishable from SQL code. No wrapper, sanitizer, or WAF can reliably tell which parts were "intended SQL" and which were "user input" after concatenation has occurred.

## Why It's Fundamentally Impossible

```python
# Your existing code (can't change):
user_input = "'; DROP TABLE users; --"
query = f"SELECT * FROM users WHERE name = '{user_input}'"
# Result: SELECT * FROM users WHERE name = ''; DROP TABLE users; --'
#                              ^^^^--- this is now valid SQL code, not data
```

After concatenation, `DROP TABLE users` is structurally identical to any other SQL keyword. There's no way to "un-concatenate" it without knowing which parts were user input — which requires changing the code.

---

## What You Can Actually Do (Defense in Depth)

Since you can't change queries, here's the best you can do — **three layers that work together**. None alone is sufficient, but together they significantly reduce risk.

### Layer 1: WAF Middleware (blocks obvious attacks)

```python
# waf.py
from flask import Flask, request, abort
import re

app = Flask(__name__)

# Common SQL injection patterns
# LIMITATION: Blacklist approach — can be bypassed with encoding, comments, etc.
SQL_PATTERNS = [
    r"'\s*OR\s+'?\d*'?\s*=\s*'?\d*",   # ' OR '1'='1
    r"'\s*;\s*DROP\s+",                  # '; DROP
    r"'\s*;\s*DELETE\s+",                # '; DELETE
    r"'\s*;\s*UPDATE\s+",                # '; UPDATE
    r"UNION\s+SELECT",                   # UNION SELECT
    r"--\s*$",                           # SQL line comment
    r"/\*.*?\*/",                        # SQL block comment
    r"\bEXEC\s+",                        # EXEC
    r"\bxp_\w+",                         # xp_cmdshell etc.
    r"\bWAITFOR\s+DELAY",                # time-based blind
    r"\bBENCHMARK\s*\(",                 # time-based blind
    r"SLEEP\s*\(",                       # time-based blind
]

def is_suspicious(value):
    if not isinstance(value, str):
        return False
    return any(re.search(p, value, re.IGNORECASE) for p in SQL_PATTERNS)

def scan(obj):
    """Recursively scan dicts/lists/strings for suspicious content."""
    if isinstance(obj, dict):
        return any(scan(v) for v in obj.values())
    if isinstance(obj, list):
        return any(scan(v) for v in obj)
    if isinstance(obj, str):
        return is_suspicious(obj)
    return False

@app.before_request
def waf_check():
    if scan(request.args.to_dict(flat=False)):
        abort(403, description="Forbidden")
    if scan(request.form.to_dict(flat=False)):
        abort(403, description="Forbidden")
    if request.is_json:
        if scan(request.get_json(silent=True)):
            abort(403, description="Forbidden")
```

### Layer 2: Database Permissions (limits damage of a successful injection)

```sql
-- permissions.sql  (run as DB admin)

-- MySQL
CREATE USER 'app_user'@'localhost' IDENTIFIED BY 'strong_password';

-- Grant ONLY what the app needs
GRANT SELECT, INSERT, UPDATE ON myapp.users   TO 'app_user'@'localhost';
GRANT SELECT            ON myapp.products TO 'app_user'@'localhost';

-- Explicitly revoke dangerous privileges
REVOKE DROP, DELETE, ALTER, CREATE, TRUNCATE, REFERENCES
    ON myapp.* FROM 'app_user'@'localhost';
FLUSH PRIVILEGES;

-- PostgreSQL
CREATE USER app_user WITH PASSWORD 'strong_password';
GRANT SELECT, INSERT, UPDATE ON users   TO app_user;
GRANT SELECT            ON products TO app_user;
-- No DROP/DELETE/ALTER/CREATE/TRUNCATE
```

Now even if injection succeeds, the attacker can't `DROP` tables or `DELETE` data.

### Layer 3: Best-Effort Query Wrapper (fragile, last resort)

This monkey-patches the DB driver to escape string literals. **It will break some legitimate queries and miss some attacks** — but it's something.

```python
# safe_db.py  — import this BEFORE any other module that uses sqlite3
import sqlite3, re

_orig_exec = sqlite3.Cursor.execute

_STRING_LITERAL = re.compile(r"'(?:[^']|'')*'")  # '...' or ''

def _escape_literals(query: str) -> str:
    """Double any single-quote inside string literals."""
    def repl(m):
        inner = m.group(0)[1:-1].replace("'", "''")
        return "'" + inner + "'"
    return _STRING_LITERAL.sub(repl, query)

def safe_execute(self, query, params=None):
    if params is not None:
        # Caller already used placeholders — safe
        return _orig_exec(self, query, params)
    # Best-effort: escape string literals
    return _orig_exec(self, _escape_literals(query))

sqlite3.Cursor.execute = safe_execute
```

**Why this is fragile:**
- Doesn't protect numeric injections: `WHERE id = {input}` — no quotes to escape.
- Breaks legitimate input containing apostrophes (names like `O'Brien`).
- Doesn't stop attacks that don't need to break out of a string (e.g., second-order injection, UNION in numeric contexts).

---

## Complete Working Example

```python
# app.py
from flask import Flask, request, jsonify, abort
import sqlite3, re

# --- Layer 3: import wrapper first ---
import safe_db  # noqa: F401  (patches sqlite3)

app = Flask(__name__)

# --- Layer 1: WAF ---
SQL_PATTERNS = [
    r"'\s*OR\s+'?\d*'?\s*=\s*'?\d*",
    r"'\s*;\s*DROP\s+", r"'\s*;\s*DELETE\s+",
    r"UNION\s+SELECT", r"--\s*$", r"/\*.*?\*/",
    r"\bEXEC\s+", r"\bxp_\w+",
    r"\bWAITFOR\s+DELAY", r"\bBENCHMARK\s*\(", r"SLEEP\s*\(",
]
def is_suspicious(v):
    return isinstance(v, str) and any(
        re.search(p, v, re.IGNORECASE) for p in SQL_PATTERNS
    )
def scan(o):
    if isinstance(o, dict):  return any(scan(v) for v in o.values())
    if isinstance(o, list):  return any(scan(v) for v in o)
    if isinstance(o, str):   return is_suspicious(o)
    return False

@app.before_request
def waf():
    if scan(request.args.to_dict(flat=False)):  abort(403)
    if scan(request.form.to_dict(flat=False)):  abort(403)
    if request.is_json and scan(request.get_json(silent=True)): abort(403)

# --- Layer 2: connect as restricted user (see permissions.sql) ---
def get_db():
    # In production: connect with the restricted 'app_user'
    conn = sqlite3.connect("app.db")
    conn.row_factory = sqlite3.Row
    return conn

# --- Your existing routes (queries unchanged) ---
@app.route("/user")
def get_user():
    user_id = request.args.get("id", "")
    db = get_db()
    cur = db.cursor()
    # Query unchanged from your original code:
    cur.execute(f"SELECT * FROM users WHERE id = '{user_id}'")
    row = cur.fetchone()
    return jsonify(dict(row) if row else {"error": "not found"})

if __name__ == "__main__":
    app.run(debug=True)
```

---

## How Each Layer Works

| Layer | What it does | What it doesn't do |
|---|---|---|
| **WAF** | Blocks requests matching known attack patterns | Stop novel encodings, blind injections, or logic abuse |
| **DB permissions** | Limits what a successful injection can do | Prevent the injection itself |
| **String-escape wrapper** | Doubles quotes inside string literals | Handle numeric contexts, second-order attacks, or non-string inputs |

## Recommendation

**Push back on the "no query changes" requirement.** Parameterized queries are the *only* way to actually solve SQL injection. The three layers above reduce risk meaningfully, but they are **mitigations, not immunity** — and any of them can be bypassed by a sufficiently motivated attacker.

If changing queries truly isn't possible, at minimum:
1. Deploy the WAF in front of the app.
2. Lock down the DB user to the absolute minimum privileges.
3. Add monitoring/alerts on unusual query patterns.
4. Schedule a refactor to parameterized queries as soon as you can.

# PBFT in C++ (n = 3f + 1)

Below is a single-file, runnable educational implementation of **Practical Byzantine Fault Tolerance** (Castro & Liskov, 1999). It uses `n = 4` replicas (`f = 1`), so it tolerates **one arbitrary (Byzantine) failure** and requires a quorum of `2f+1 = 3`.

## How PBFT works (the 30-second version)

```
Client → Primary: REQUEST
Primary → Replicas: PRE-PREPARE   (assigns seq#, binds request via digest)
Replicas → Replicas: PREPARE      (2f matching prepares → PREPARED)
Replicas → Replicas: COMMIT       (2f matching commits  → COMMITTED → execute)
```

**Why `n = 3f + 1`?** A quorum of `2f + 1` overlaps any other quorum by at least `f + 1` replicas. Since at most `f` are Byzantine, the overlap always contains at least one honest replica — so honest replicas can never disagree on the order.

**Failure handling** has three layers:
1. **Digest checks** — Byzantine messages with wrong digests are silently rejected.
2. **View numbers** — old-view messages are ignored, preventing replay attacks.
3. **View changes** — if the primary is unresponsive or equivocates, replicas rotate to a new primary (`view + 1` mod `n`).

## The code

Save as `pbft.cpp`, build with `g++ -std=c++17 -pthread pbft.cpp -o pbft`, run with `./pbft`.

```cpp
// pbft.cpp — Educational PBFT (Castro-Liskov 1999)
// n = 3f + 1 replicas, tolerates f Byzantine failures.
// Phases: Pre-Prepare → Prepare → Commit → Execute
// Failure handling: digest checks, view numbers, view-change protocol.
//
// Build: g++ -std=c++17 -pthread pbft.cpp -o pbft
// Run:   ./pbft

#include <algorithm>
#include <atomic>
#include <chrono>
#include <functional>
#include <iomanip>
#include <iostream>
#include <map>
#include <memory>
#include <mutex>
#include <random>
#include <set>
#include <sstream>
#include <string>
#include <thread>
#include <vector>

namespace pbft {

// ============================================================================
// Digest — replace std::hash with SHA-256 + digital signatures in production.
// ============================================================================
inline std::string digest(const std::string& s) {
    std::hash<std::string> h;
    std::ostringstream o;
    o << std::hex << std::setw(16) << std::setfill('0') << h(s);
    return o.str();
}

// ============================================================================
// Types
// ============================================================================
using View    = int;
using SeqNum  = int;
using ReplicaId = int;

// ============================================================================
// Message — every PBFT message carries (view, seq, digest) to bind it.
// ============================================================================
enum class MsgType {
    REQUEST, PRE_PREPARE, PREPARE, COMMIT, REPLY, VIEW_CHANGE, NEW_VIEW
};

struct Message {
    MsgType  type;
    View     view = 0;
    SeqNum   seq  = 0;
    ReplicaId sender = -1;
    std::string d;        // digest of the client request
    std::string payload;  // operation (REQUEST / PRE_PREPARE only)

    // VIEW_CHANGE carries the P-set: prepared proofs this replica has seen.
    std::map<SeqNum, std::shared_ptr<Message>> prepared;

    std::string tn() const {
        switch (type) {
            case MsgType::REQUEST:     return "REQUEST";
            case MsgType::PRE_PREPARE: return "PRE-PREPARE";
            case MsgType::PREPARE:     return "PREPARE";
            case MsgType::COMMIT:      return "COMMIT";
            case MsgType::REPLY:       return "REPLY";
            case MsgType::VIEW_CHANGE: return "VIEW-CHANGE";
            case MsgType::NEW_VIEW:    return "NEW-VIEW";
        }
        return "?";
    }
};

// ============================================================================
// LogEntry — per-request state machine:
//   NONE → PRE_PREPARED → PREPARED → COMMITTED → EXECUTED
// ============================================================================
enum class Phase { NONE, PRE_PREPARED, PREPARED, COMMITTED, EXECUTED };

struct LogEntry {
    Phase phase = Phase::NONE;
    std::shared_ptr<Message> pre_prepare;
    std::set<ReplicaId> prepares;   // replicas that sent matching PREPARE
    std::set<ReplicaId> commits;    // replicas that sent matching COMMIT
    std::string payload;
};

// ============================================================================
// Network — simulated async network with failure injection.
// Replace with real sockets + auth in production.
// ============================================================================
class Network {
public:
    using Handler = std::function<void(const Message&)>;

    static Network& get() { static Network n; return n; }

    void register_replica(ReplicaId id, Handler h) {
        std::lock_guard<std::mutex> lk(mu_);
        handlers_[id] = std::move(h);
    }

    void send(ReplicaId to, const Message& m) {
        if (drop_rule_ && drop_rule_(to, m)) {
            std::lock_guard<std::mutex> lk(cout_mu_);
            std::cout << "  [net] x DROP -> R" << to << " " << m.tn() << "\n";
            return;
        }
        {
            std::lock_guard<std::mutex> lk(cout_mu_);
            std::cout << "  [net] -> R" << to << " " << m.tn()
                      << " v=" << m.view << " s=" << m.seq << "\n";
        }
        // Async delivery to simulate network delay.
        std::thread([this, to, m] {
            std::this_thread::sleep_for(std::chrono::milliseconds(delay_ms_));
            std::lock_guard<std::mutex> lk(mu_);
            auto it = handlers_.find(to);
            if (it != handlers_.end()) it->second(m);
        }).detach();
    }

    void broadcast(const std::vector<ReplicaId>& ids, const Message& m,
                   ReplicaId skip = -1) {
        for (auto id : ids) if (id != skip) send(id, m);
    }

    void set_drop_rule(std::function<bool(ReplicaId, const Message&)> rule) {
        drop_rule_ = std::move(rule);
    }
    void reset() { drop_rule_ = nullptr; delay_ms_ = 2; }
    void set_delay(int ms) { delay_ms_ = ms; }

    std::mutex cout_mu_;

private:
    std::mutex mu_;
    std::map<ReplicaId, Handler> handlers_;
    std::function<bool(ReplicaId, const Message&)> drop_rule_;
    int delay_ms_ = 2;
};

// ============================================================================
// Replica — the core PBFT state machine.
// ============================================================================
class Replica {
public:
    Replica(ReplicaId id, int f, std::vector<ReplicaId> all)
        : id_(id), f_(f), n_(int(all.size())), all_(std::move(all)),
          view_(0), seq_(0),
          last_activity_(std::chrono::steady_clock::now()) {}

    ~Replica() { stop(); }

    void start() {
        running_ = true;
        timer_thread_ = std::thread([this] { timer_loop(); });
    }
    void stop() {
        running_ = false;
        if (timer_thread_.joinable()) timer_thread_.join();
    }

    ReplicaId id()        const { return id_; }
    bool      is_primary() const { return id_ == view_ % n_; }
    int       quorum()    const { return 2 * f_ + 1; }
    View      view()      const { return view_; }

    // ---- Message entry point ----
    void receive(const Message& m) {
        std::lock_guard<std::mutex> lk(mu_);
        last_activity_ = std::chrono::steady_clock::now();
        switch (m.type) {
            case MsgType::REQUEST:     on_request(m);     break;
            case MsgType::PRE_PREPARE: on_pre_prepare(m); break;
            case MsgType::PREPARE:     on_prepare(m);     break;
            case MsgType::COMMIT:      on_commit(m);      break;
            case MsgType::VIEW_CHANGE: on_view_change(m); break;
            case MsgType::NEW_VIEW:    on_new_view(m);    break;
            default: break;
        }
    }

    // ---- Client API ----
    void client_request(const std::string& op) {
        std::lock_guard<std::mutex> lk(mu_);
        last_activity_ = std::chrono::steady_clock::now();
        on_request(Message{MsgType::REQUEST, view_, 0, -1, digest(op), op, {}});
    }

    void set_byzantine(bool b) { byzantine_ = b; }

private:
    // ---- Identity / config ----
    ReplicaId id_;
    int f_, n_;
    std::vector<ReplicaId> all_;
    View    view_;
    SeqNum  seq_;

    // ---- State ----
    std::mutex mu_;
    std::map<SeqNum, LogEntry> log_;
    bool byzantine_ = false;

    // ---- Failure detector ----
    std::atomic<bool> running_{false};
    std::thread timer_thread_;
    std::chrono::steady_clock::time_point last_activity_;

    void log(const std::string& s) {
        std::lock_guard<std::mutex> lk(Network::get().cout_mu_);
        std::cout << "[R" << id_ << " v=" << view_ << "] " << s << "\n";
    }

    // =========================================================================
    // PHASE 1 — REQUEST -> PRE-PREPARE  (primary only)
    // =========================================================================
    // The primary assigns a sequence number and broadcasts. This is what
    // establishes *total order* within a view.
    void on_request(const Message& m) {
        if (!is_primary()) {
            log("ignored REQUEST (not primary)");
            return;
        }
        SeqNum s = ++seq_;
        Message pp{MsgType::PRE_PREPARE, view_, s, id_, m.d, m.payload, {}};
        log_[s] = LogEntry{Phase::PRE_PREPARED,
                           std::make_shared<Message>(pp), {}, {}, m.payload};
        log("PRIMARY: PRE-PREPARE s=" + std::to_string(s) +
            " op=\"" + m.payload + "\"");
        Network::get().broadcast(all_, pp, id_);
    }

    // =========================================================================
    // PHASE 2 — PRE-PREPARE -> PREPARE
    // =========================================================================
    // Safety checks (reject anything fishy):
    //   1. Sender must be the current primary (view_ % n_)
    //   2. View number must match ours
    //   3. We haven't already accepted a different PRE-PREPARE for this seq
    //
    // A replica is PREPARED when it has:
    //   - 1 PRE_PREPARE from the primary
    //   - 2f matching PREPAREs from *other* replicas (our own is implicit)
    //
    // Why 2f? Among 2f+1 replicas at most f are Byzantine, so at least f+1
    // honest replicas have the request. That guarantees any future view
    // (with a different primary) will also see it.
    void on_pre_prepare(const Message& m) {
        if (m.sender != view_ % n_) {
            log("REJECT PRE-PREPARE: not from primary (sender=R"
                + std::to_string(m.sender) + ")");
            return;
        }
        if (m.view != view_) {
            log("REJECT PRE-PREPARE: view mismatch");
            return;
        }
        if (log_.count(m.seq)) return;  // already have it

        log_[m.seq] = LogEntry{Phase::PRE_PREPARED,
                               std::make_shared<Message>(m), {}, {}, m.payload};
        log("<- PRE-PREPARE s=" + std::to_string(m.seq) + " -> send PREPARE");

        Message p{MsgType::PREPARE, view_, m.seq, id_, m.d, "", {}};
        Network::get().broadcast(all_, p, id_);
    }

    void on_prepare(const Message& m) {
        if (m.view != view_) return;
        auto it = log_.find(m.seq);
        if (it == log_.end()) return;
        auto& e = it->second;

        // Byzantine check: digest must match the PRE-PREPARE we accepted.
        // This is what catches equivocation (primary sending different
        // requests with the same seq# to different replicas).
        if (!e.pre_prepare || m.d != e.pre_prepare->d) {
            log("REJECT PREPARE s=" + std::to_string(m.seq) + ": digest mismatch");
            return;
        }

        e.prepares.insert(m.sender);

        if (e.phase == Phase::PRE_PREPARED &&
            int(e.prepares.size()) >= 2 * f_) {
            e.phase = Phase::PREPARED;
            log("v PREPARED s=" + std::to_string(m.seq) +
                " (" + std::to_string(e.prepares.size()) + " prepares)");

            Message c{MsgType::COMMIT, view_, m.seq, id_, m.d, "", {}};
            Network::get().broadcast(all_, c, id_);
        }
    }

    // =========================================================================
    // PHASE 3 — COMMIT
    // =========================================================================
    // After PREPARED, broadcast COMMIT. Committed when 2f+1 matching
    // COMMITs are received. This phase guarantees that even if some
    // replicas crash after preparing, enough others have the request to
    // ensure it will be executed in every future view.
    void on_commit(const Message& m) {
        if (m.view != view_) return;
        auto it = log_.find(m.seq);
        if (it == log_.end()) return;
        auto& e = it->second;

        if (e.phase < Phase::PREPARED) return;  // not ready yet
        if (m.d != e.pre_prepare->d) {
            log("REJECT COMMIT s=" + std::to_string(m.seq) + ": digest mismatch");
            return;
        }

        e.commits.insert(m.sender);

        if (e.phase == Phase::PREPARED &&
            int(e.commits.size()) >= 2 * f_) {
            e.phase = Phase::COMMITTED;
            log("v COMMITTED s=" + std::to_string(m.seq) +
                " (" + std::to_string(e.commits.size()) + " commits)");
            execute(m.seq, e.payload);
        }
    }

    // =========================================================================
    // PHASE 4 — EXECUTE
    // =========================================================================
    void execute(SeqNum s, const std::string& op) {
        log_[s].phase = Phase::EXECUTED;
        log("> EXECUTE s=" + std::to_string(s) + " op=\"" + op + "\"");
        // In a real system: apply to state machine, send REPLY to client.
    }

    // =========================================================================
    // VIEW CHANGE — failure recovery
    // =========================================================================
    // Triggered when:
    //   * Primary times out (no PRE-PREPARE for a client request)
    //   * Replica detects equivocation (digest mismatch)
    //
    // Protocol (simplified):
    //   1. Replica broadcasts VIEW_CHANGE for view v+1, including its
    //      prepared proofs (the P-set).
    //   2. New primary = (v+1) mod n collects 2f+1 VIEW_CHANGEs.
    //   3. New primary broadcasts NEW_VIEW containing those view-changes
    //      plus new PRE-PREPAREs for any requests that were prepared but
    //      not committed.
    //   4. Replicas verify NEW_VIEW and enter the new view.
    void on_view_change(const Message& m) {
        log("<- VIEW-CHANGE from R" + std::to_string(m.sender) +
            " for view " + std::to_string(m.view));
    }

    void on_new_view(const Message& m) {
        log("<- NEW-VIEW entering view " + std::to_string(m.view));
        view_ = m.view;
    }

    void trigger_view_change(const std::string& reason) {
        log("! VIEW CHANGE triggered: " + reason);
        View nv = view_ + 1;
        Message vc{MsgType::VIEW_CHANGE, nv, 0, id_, "", "", {}};
        for (auto& [s, e] : log_) {
            if (e.phase >= Phase::PREPARED) {
                vc.prepared[s] = e.pre_prepare;
            }
        }
        Network::get().broadcast(all_, vc, id_);
        view_ = nv;
    }

    // =========================================================================
    // TIMEOUT / FAILURE DETECTOR
    // =========================================================================
    // Each replica runs a timer. If a request stalls (no progress), the
    // replica suspects the primary and triggers a view change.
    void timer_loop() {
        while (running_) {
            std::this_thread::sleep_for(std::chrono::milliseconds(200));
            std::lock_guard<std::mutex> lk(mu_);
            auto now = std::chrono::steady_clock::now();
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                now - last_activity_).count();

            if (!is_primary() && !log_.empty() && elapsed > 1000) {
                bool stuck = false;
                for (auto& [s, e] : log_) {
                    if (e.phase < Phase::COMMITTED) { stuck = true; break; }
                }
                if (stuck) {
                    trigger_view_change("timeout: no progress for 1s");
                    last_activity_ = now;
                }
            }
        }
