    const int f = 1, n = 4;
    std::vector<ReplicaId> ids = {0, 1, 2, 3};

    auto setup = [&]() {
        std::vector<std::unique_ptr<Replica>> rs;
        for (int i = 0; i < n; ++i) {
            rs.push_back(std::make_unique<Replica>(i, f, ids));
            rs.back()->start();
        }
        for (auto& r : rs) {
            Network::get().register_replica(r->id(),
                [ptr = r.get()](const Message& m) { ptr->receive(m); });
        }
        return rs;
    };

    auto teardown = [](std::vector<std::unique_ptr<Replica>>& rs) {
        for (auto& r : rs) r->stop();
        rs.clear();
        Network::get().reset();
    };

    // -----------------------------------------------------------------------
    // Scenario 1: Normal operation
    // -----------------------------------------------------------------------
    {
        std::cout << "--- Scenario 1: Normal Operation ---\n";
        std::cout << "View 0, primary = R0\n\n";
        auto rs = setup();
        rs[0]->client_request("transfer(Alice, Bob, 10)");
        std::this_thread::sleep_for(500ms);
        std::cout << "\n-> All 4 replicas execute the same operation.\n\n";
        teardown(rs);
    }

    // -----------------------------------------------------------------------
    // Scenario 2: Byzantine primary equivocation
    // -----------------------------------------------------------------------
    // The primary sends DIFFERENT requests with the same (view, seq#) to
    // different replicas. Honest replicas detect this because the digests
    // don't match, and reject the conflicting messages.
    {
        std::cout << "--- Scenario 2: Byzantine Primary (equivocation) ---\n";
        std::cout << "Primary R0 sends DIFFERENT requests to different replicas.\n";
        std::cout << "Honest replicas detect this via digest mismatch.\n\n";

        auto rs = setup();

        Message pp1{MsgType::PRE_PREPARE, 0, 1, 0,
                    digest("opA: x=1"),   "opA: x=1",   {}};
        Message pp2{MsgType::PRE_PREPARE, 0, 1, 0,
                    digest("opB: x=999"), "opB: x=999", {}};

        Network::get().send(1, pp1);   // R1 sees opA
        Network::get().send(2, pp1);   // R2 sees opA
        Network::get().send(3, pp2);   // R3 sees opB  <- equivocation!

        std::this_thread::sleep_for(500ms);
        std::cout << "\n-> R1,R2 prepared \"opA\"; R3 prepared \"opB\".\n";
        std::cout << "-> No quorum -> honest replicas trigger view change.\n\n";
        teardown(rs);
    }

    // -----------------------------------------------------------------------
    // Scenario 3: Network failure (message loss)
    // -----------------------------------------------------------------------
    {
        std::cout << "--- Scenario 3: Network Failure (message loss) ---\n";
        std::cout << "30% of messages to R3 are dropped.\n";
        std::cout << "Protocol still makes progress if quorum (3) is reachable.\n\n";

        auto rs = setup();

        std::mt19937 rng(123);
        Network::get().set_drop_rule([&rng](ReplicaId to, const Message&) {
            if (to == 3) {
                std::uniform_int_distribution<int> d(0, 99);
                return d(rng) < 30;
            }
            return false;
        });

        rs[0]->client_request("transfer(Bob, Carol, 5)");
        std::this_thread::sleep_for(800ms);
        std::cout << "\n-> If R3 misses too many messages, it triggers view change.\n\n";
        teardown(rs);
    }

    // -----------------------------------------------------------------------
    // Scenario 4: View change on primary failure
    // -----------------------------------------------------------------------
    {
        std::cout << "--- Scenario 4: View Change (primary unresponsive) ---\n";
        std::cout << "Primary R0 stops responding. Replicas detect and rotate.\n\n";

        auto rs = setup();

        // Drop all messages from R0 -> primary appears unresponsive.
        Network::get().set_drop_rule(
            [](ReplicaId, const Message& m) { return m.sender == 0; });

        rs[0]->client_request("op3: z = 3");
        std::this_thread::sleep_for(1500ms);  // wait for timeout detector

        std::cout << "\n-> Replicas detected primary R0 is unresponsive.\n";
        std::cout << "-> View change triggered automatically.\n\n";
        teardown(rs);
    }

    std::cout << "=== End Demo ===\n";
    return 0;
}
