    NEW_VIEW      // New Primary → Replicas
};

struct Message {
    MsgType type;
    View view;
    SeqNum seq;
    ReplicaId sender;
    std::string request_digest;  // digest of the client request
    std::string payload;         // the actual operation (for REQUEST/PRE_PREPARE)

    // For VIEW_CHANGE messages
    std::set<ReplicaId> prepared_senders;  // which replicas sent PREPARE for this seq
    std::map<SeqNum, std::shared_ptr<Message>> prepared_proofs;  // P set

    std::string type_name() const {
        switch (type) {
            case MsgType::REQUEST: return "REQUEST";
            case MsgType::PRE_PREPARE: return "PRE_PREPARE";
            case MsgType::PREPARE: return "PREPARE";
            case MsgType::COMMIT: return "COMMIT";
            case MsgType::REPLY: return "REPLY";
            case MsgType::VIEW_CHANGE: return "VIEW_CHANGE";
            case MsgType::NEW_VIEW: return "NEW_VIEW";
        }
        return "?";
    }

    std::string debug() const {
        std::ostringstream oss;
        oss << type_name() << "{view=" << view << ", seq=" << seq
            << ", from=" << sender << ", d=" << request_digest.substr(0, 8) << "}";
        return oss.str();
    }
};

// ============================================================================
// SECTION 4: Log Entry - tracks state of each request through the protocol
// ============================================================================
// Each request goes through phases:
//   NULL → PRE_PREPARED → PREPARED → COMMITTED → EXECUTED
// Transitions require quorum (2f+1) of matching messages.

enum class Phase { NULL_PHASE, PRE_PREPARED, PREPARED, COMMITTED, EXECUTED };

struct LogEntry {
    Phase phase = Phase::NULL_PHASE;
    std::shared_ptr<Message> pre_prepare;
    std::set<ReplicaId> prepares;   // replicas that sent matching PREPARE
    std::set<ReplicaId> commits;    // replicas that sent matching COMMIT
    std::string payload;
};

