// SECTION 5: Network Simulator
// ============================================================================
// Simulates an asynchronous network with possible message loss and Byzantine
// behavior. In production, replace with real networking (TCP/UDP + auth).

class Network {
public:
    using Handler = std::function<void(const Message&)>;

    static Network& instance() {
        static Network net;
        return net;
    }

    void register_replica(ReplicaId id, Handler h) {
        std::lock_guard<std::mutex> lk(mu_);
        handlers_[id] = std::move(h);
    }

    // Send a message to one replica
    void send(ReplicaId to, const Message& m) {
        if (should_drop(to, m)) {
            log_net("DROP", to, m);
            return;
        }
        log_net("SEND", to, m);
        // Asynchronous delivery (simulates network delay)
        std::thread([this, to, m]() {
            std::this_thread::sleep_for(std::chrono::milliseconds(delay_ms_));
            std::lock_guard<std::mutex> lk(mu_);
            auto it = handlers_.find(to);
            if (it != handlers_.end()) {
                it->second(m);
            }
        }).detach();
    }

    // Broadcast to all replicas
    void broadcast(const std::vector<ReplicaId>& ids, const Message& m, ReplicaId exclude = INVALID_REPLICA) {
        for (auto id : ids) {
            if (id != exclude) send(id, m);
        }
    }

    // Failure injection: drop messages matching predicate
    void set_drop_rule(std::function<bool(ReplicaId to, const Message& m)> rule) {
        drop_rule_ = std::move(rule);
    }

    void set_delay(int ms) { delay_ms_ = ms; }

private:
    bool should_drop(ReplicaId to, const Message& m) {
        if (!drop_rule_) return false;
        return drop_rule_(to, m);
    }

    void log_net(const char* action, ReplicaId to, const Message& m) {
        std::lock_guard<std::mutex> lk(cout_mu_);
        std::cout << "  [net] " << action << " → R" << to << ": " << m.debug() << "\n";
    }

    std::mutex mu_;
    std::mutex cout_mu_;
    std::map<ReplicaId, Handler> handlers_;
    std::function<bool(ReplicaId, const Message&)> drop_rule_;
    int delay_ms_ = 1;
};

