class Replica {
public:
    Replica(ReplicaId id, int f, std::vector<ReplicaId> all_ids)
        : id_(id), f_(f), n_(static_cast<int>(all_ids.size())),
          all_ids_(std::move(all_ids)), view_(0), seq_(0) {
        assert(n_ == 3 * f_ + 1 && "PBFT requires n = 3f + 1");
    }

    ~Replica() { stop(); }

    void start() {
        running_ = true;
        timer_thread_ = std::thread([this] { timer_loop(); });
    }

    void stop() {
        running_ = false;
        cv_.notify_all();
        if (timer_thread_.joinable()) timer_thread_.join();
    }

    // ---- Public API ----

    ReplicaId id() const { return id_; }
    bool is_primary() const { return id_ == view_ % n_; }
    int quorum() const { return 2 * f_ + 1; }
    View view() const { return view_; }

    // Client submits a request (only primary processes it)
    void client_request(const std::string& operation) {
        if (!is_primary()) {
            log("Ignoring client request (not primary)");
            return;
        }
        pre_prepare(operation);
    }

    // Network delivers a message
    void receive(const Message& m) {
        std::lock_guard<std::mutex> lk(mu_);
        switch (m.type) {
            case MsgType::REQUEST:
                // Should not happen at replica (only primary sees client)
                break;
            case MsgType::PRE_PREPARE: on_pre_prepare(m); break;
            case MsgType::PREPARE:     on_prepare(m); break;
            case MsgType::COMMIT:      on_commit(m); break;
            case MsgType::VIEW_CHANGE: on_view_change(m); break;
            case MsgType::NEW_VIEW:    on_new_view(m); break;
            default: break;
        }
    }

    // For testing: make this replica Byzantine
    void set_byzantine(bool b) { byzantine_ = b; }
    bool is_byzantine() const { return byzantine_; }

private:
    // ---- Identity & config ----
    ReplicaId id_;
    int f_;
    int n_;
    std::vector<ReplicaId> all_ids_;
    View view_;
    SeqNum seq_;

    // ---- State ----
    std::mutex mu_;
    std::map<SeqNum, LogEntry> log_;
    std::set<SeqNum> timed_out_;  // sequences we've given up on

    // ---- Threading ----
    std::atomic<bool> running_{false};
    std::condition_variable cv_;
    std::thread timer_thread_;

    // ---- Fault injection ----
    bool byzantine_ = false;

    // =========================================================================
    // SECTION 6.1: Pre-Prepare Phase
    // =========================================================================
    // The primary assigns a sequence number to the request and broadcasts it.
    // This establishes a total order within a view.

    void pre_prepare(const std::string& operation) {
        SeqNum n = ++seq_;
        std::string d = digest(operation);

        Message pp;
        pp.type = MsgType::PRE_PREPARE;
        pp.view = view_;
        pp.seq = n;
        pp.sender = id_;
        pp.request_digest = d;
        pp.payload = operation;

        log_entry(n).phase = Phase::PRE_PREPARED;
        log_entry(n).pre_prepare = std::make_shared<Message>(pp);
        log_entry(n).payload = operation;

        log("PRIMARY: PRE-PREPARE seq=" + std::to_string(n) + " op=\"" + operation + "\"");

        Network::instance().broadcast(all_ids_, pp, id_);
    }

    // =========================================================================
    // SECTION 6.2: Prepare Phase
    // =========================================================================
    // Replicas verify the PRE-PREPARE came from the correct primary and matches
    // the request digest. They then broadcast PREPARE messages.
    // 
    // A replica is "prepared" when it has:
    //   - 1 PRE_PREPARE from the primary (for this view, seq, digest)
    //   - 2f matching PREPAREs from different replicas (including its own)
    //
    // This ensures that at least f+1 honest replicas have seen the request,
    // which is enough to guarantee that any future view will also see it.

    void on_pre_prepare(const Message& m) {
        // Safety check 1: must be from current primary
        if (m.sender != primary_id()) {
            log("REJECTED PRE-PREPARE: not from primary (sender=" + std::to_string(m.sender) + ")");
            return;
        }
        // Safety check 2: view must match
        if (m.view != view_) {
            log("REJECTED PRE-PREPARE: view mismatch");
            return;
        }
        // Safety check 3: not already processing this seq
        if (log_.count(m.seq)) {
            return;  // already have it
        }

        log_entry(m.seq).phase = Phase::PRE_PREPARED;
        log_entry(m.seq).pre_prepare = std::make_shared<Message>(m);
        log_entry(m.seq).payload = m.payload;

        log("← PRE-PREPARE seq=" + std::to_string(m.seq) + " → sending PREPARE");

        // Broadcast PREPARE
        Message p;
        p.type = MsgType::PREPARE;
        p.view = m.view;
        p.seq = m.seq;
        p.sender = id_;
        p.request_digest = m.request_digest;

        Network::instance().broadcast(all_ids_, p, id_);
    }

    void on_prepare(const Message& m) {
        if (m.view != view_) return;
        auto it = log_.find(m.seq);
        if (it == log_.end()) return;
        auto& entry = it->second;

        // Safety check: digest must match our PRE_PREPARE
        if (entry.pre_prepare == nullptr || m.request_digest != entry.pre_prepare->request_digest) {
            log("REJECTED PREPARE: digest mismatch seq=" + std::to_string(m.seq));
            return;
        }

        entry.prepares.insert(m.sender);

        // Check quorum: we have 2f PREPAREs (including our own implicit one)
        // We need 2f+1 total agreement, but we don't send PREPARE to ourselves,
        // so we count 2f from others.
        if (entry.phase == Phase::PRE_PREPARED &&
            static_cast<int>(entry.prepares.size()) >= 2 * f_) {
            entry.phase = Phase::PREPARED;
            log("✓ PREPARED seq=" + std::to_string(m.seq) + 
                " (" + std::to_string(entry.prepares.size()) + " prepares)");

            // Broadcast COMMIT
            Message c;
            c.type = MsgType::COMMIT;
            c.view = m.view;
            c.seq = m.seq;
            c.sender = id_;
            c.request_digest = m.request_digest;

            Network::instance().broadcast(all_ids_, c, id_);
        }
    }

    // =========================================================================
    // SECTION 6.3: Commit Phase
    // =========================================================================
    // After PREPARED, replicas broadcast COMMIT. A replica is "committed" when
    // it has 2f+1 matching COMMITs. This ensures that even if some replicas
    // crash after preparing, enough others have the request to guarantee
    // it will be executed in all future views.

    void on_commit(const Message& m) {
        if (m.view != view_) return;
        auto it = log_.find(m.seq);
        if (it == log_.end()) return;
        auto& entry = it->second;

        // Must be PREPARED first (or beyond)
        if (entry.phase < Phase::PREPARED) {
            return;  // not ready to commit yet
        }

        // Safety check: digest must match
        if (m.request_digest != entry.pre_prepare->request_digest) {
            log("REJECTED COMMIT: digest mismatch seq=" + std::to_string(m.seq));
            return;
        }

        entry.commits.insert(m.sender);

        if (entry.phase == Phase::PREPARED &&
            static_cast<int>(entry.commits.size()) >= 2 * f_) {
            entry.phase = Phase::COMMITTED;
            log("✓ COMMITTED seq=" + std::to_string(m.seq) + 
                " (" + std::to_string(entry.commits.size()) + " commits)");

            execute(m.seq, entry.payload);
        }
    }

    // =========================================================================
    // SECTION 6.4: Execution
    // =========================================================================

    void execute(SeqNum seq, const std::string& payload) {
        entry(seq).phase = Phase::EXECUTED;
        log("▶ EXECUTE seq=" + std::to_string(seq) + " op=\"" + payload + "\"");
        // In real system: apply to state machine, send REPLY to client
    }

    // =========================================================================
    // SECTION 6.5: View Change Protocol (Failure Handling)
    // =========================================================================
    // Triggered when a replica suspects the primary is faulty (timeout).
    // 
    // Steps:
    //   1. Replica stops accepting messages in current view
    //   2. Sends VIEW_CHANGE to all replicas (with prepared proofs)
    //   3. When new primary collects 2f+1 VIEW_CHANGE messages, it broadcasts
    //      NEW_VIEW with the set of view changes
    //   4. Replicas verify NEW_VIEW and enter new view
    //
    // This is the core failure recovery mechanism. It ensures liveness even
    // when the primary is Byzantine or crashed.

    void on_view_change(const Message& m) {
        // Simplified: collect view changes, trigger new view when quorum reached
        log("← VIEW_CHANGE from R" + std::to_string(m.sender) + " for view " + std::to_string(m.view + 1));
        // (Full implementation would collect and verify, then trigger new view)
    }

    void on_new_view(const Message& m) {
        log("← NEW_VIEW for view " + std::to_string(m.view));
        view_ = m.view;
        // (Full implementation would re-apply prepared proofs from view changes)
    }

    void trigger_view_change(const std::string& reason) {
        log("⚠ VIEW CHANGE triggered: " + reason);
        View new_view = view_ + 1;

        Message vc;
        vc.type = MsgType::VIEW_CHANGE;
        vc.view = new_view;
        vc.sender = id_;

        // Include prepared proofs (P set) - requests we've prepared in this view
        for (auto& [seq, entry] : log_) {
            if (entry.phase >= Phase::PREPARED) {
                vc.prepared_proofs[seq] = entry.pre_prepare;
                vc.prepared_senders.insert(entry.prepares.begin(), entry.prepares.end());
            }
        }

        Network::instance().broadcast(all_ids_, vc, id_);
        view_ = new_view;
    }

    // =========================================================================
    // SECTION 6.6: Timeout / Failure Detection
    // =========================================================================
    // Each replica runs a timer. If a request doesn't progress through phases
    // within a timeout, the replica suspects the primary is faulty and triggers
    // a view change.

    void timer_loop() {
        while (running_) {
            std::unique_lock<std::mutex> lk(mu_);
            cv_.wait_for(lk, std::chrono::milliseconds(500), [this] { return !running_; });

            // Check for stuck requests
            for (auto& [seq, entry] : log_) {
                if (entry.phase < Phase::COMMITTED && timed_out_.count(seq) == 0) {
                    // In a real implementation, we'd track time-since-pre-prepare
                    // and trigger view change if too old. For this demo, we
                    // rely on the test scenarios to inject failures.
                }
            }
        }
    }

    // ---- Helpers ----

    ReplicaId primary_id() const { return view_ % n_; }

    LogEntry& log_entry(SeqNum seq) { return log_[seq]; }
    LogEntry& entry(SeqNum seq) { return log_[seq]; }

    void log(const std::string& msg) {
        std::lock_guard<std::mutex> lk(cout_mu_);
        std::cout << "[R" << id_ << " v=" << view_ << "] " << msg << "\n";
    }

    static std::mutex& cout_mu() {
        static std::mutex m;
        return m;
    }
};

