// ============================================================================
// Utility: Digest (use SHA-256 in production)
// ============================================================================
static std::string digest(const std::string& s) {
    std::hash<std::string> h;
    std::ostringstream o;
    o << std::hex << std::setw(16) << std::setfill('0') << h(s);
    return o.str();
}

