// pbft.cpp - Educational PBFT (Practical Byzantine Fault Tolerance)
// Implements Castro-Liskov 1999 with n = 3f + 1 replicas.
//
// Build: g++ -std=c++17 -pthread pbft.cpp -o pbft
// Run:   ./pbft

#include <algorithm>
#include <atomic>
#include <chrono>
#include <condition_variable>
#include <functional>
#include <iomanip>
#include <iostream>
#include <map>
#include <memory>
#include <mutex>
#include <random>
#include <set>
#include <sstream>
#include <string>
#include <thread>
#include <vector>

namespace pbft {

// ============================================================================
// Digest (use SHA-256 + digital signatures in production)
// ============================================================================
inline std::string digest(const std::string& s) {
    std::hash<std::string> h;
    std::ostringstream o;
    o << std::hex << std::setw(16) << std::setfill('0') << h(s);
    return o.str();
}

// ============================================================================
// Types
// ============================================================================
using View = int;
using SeqNum = int;
using ReplicaId = int;

// ============================================================================
// Message
// ============================================================================
enum class MsgType { 
    REQUEST, PRE_PREPARE, PREPARE, COMMIT, REPLY, VIEW_CHANGE, NEW_VIEW 
};

struct Message {
    MsgType type;
    View view = 0;
    SeqNum seq = 0;
    ReplicaId sender = -1;
    std::string d;       // digest of request
    std::string payload; // operation (for REQUEST/PRE_PREPARE)

    // For VIEW_CHANGE: prepared proofs (P set)
    std::map<SeqNum, std::shared_ptr<Message>> prepared;

    std::string tn() const {
        switch (type) {
            case MsgType::REQUEST: return "REQUEST";
            case MsgType::PRE_PREPARE: return "PRE-PREPARE";
            case MsgType::PREPARE: return "PREPARE";
            case MsgType::COMMIT: return "COMMIT";
            case MsgType::REPLY: return "REPLY";
            case MsgType::VIEW_CHANGE: return "VIEW-CHANGE";
            case MsgType::NEW_VIEW: return "NEW-VIEW";
        }
        return "?";
    }
};

// ============================================================================
// Log Entry
// ============================================================================
enum class Phase { NONE, PRE_PREPARED, PREPARED, COMMITTED, EXECUTED };

struct LogEntry {
    Phase phase = Phase::NONE;
    std::shared_ptr<Message> pre_prepare;
    std::set<ReplicaId> prepares;
    std::set<ReplicaId> commits;
    std::string payload;
};

// ============================================================================
// Network (simulated, with failure injection)
// ============================================================================
class Network {
public:
    using Handler = std::function<void(const Message&)>;

    static Network& get() {
        static Network n;
        return n;
    }

    void register_replica(ReplicaId id, Handler h) {
        std::lock_guard<std::mutex> lk(mu_);
        handlers_[id] = std::move(h);
    }

    void send(ReplicaId to, const Message& m) {
        if (drop_rule_ && drop_rule_(to, m)) {
            std::lock_guard<std::mutex> lk(cout_mu_);
            std::cout << "  [net] ✗ DROP → R" << to << " " << m.tn() << "\n";
            return;
        }
        {
            std::lock_guard<std::mutex> lk(cout_mu_);
            std::cout << "  [net] → R" << to << " " << m.tn() 
                      << " v=" << m.view << " s=" << m.seq << "\n";
        }
        std::thread([this, to, m] {
            std::this_thread::sleep_for(std::chrono::milliseconds(delay_ms_));
            std::lock_guard<std::mutex> lk(mu_);
            auto it = handlers_.find(to);
            if (it != handlers_.end()) it->second(m);
        }).detach();
    }

    void broadcast(const std::vector<ReplicaId>& ids, const Message& m, ReplicaId skip = -1) {
        for (auto id : ids) if (id != skip) send(id, m);
    }

    void set_drop_rule(std::function<bool(ReplicaId, const Message&)> rule) {
        drop_rule_ = std::move(rule);
    }

    void reset() {
        drop_rule_ = nullptr;
        delay_ms_ = 2;
    }

    void set_delay(int ms) { delay_ms_ = ms; }

    std::mutex cout_mu_;

private:
    std::mutex mu_;
    std::map<ReplicaId, Handler> handlers_;
    std::function<bool(ReplicaId, const Message&)> drop_rule_;
    int delay_ms_ = 2;
};

// ============================================================================
// Replica
// ============================================================================
class Replica {
public:
    Replica(ReplicaId id, int f, std::vector<ReplicaId> all)
        : id_(id), f_(f), n_(int(all.size())), all_(std::move(all)), 
          view_(0), seq_(0), last_activity_(std::chrono::steady_clock::now()) {}

    ~Replica() { stop(); }

    void start() {
        running_ = true;
        timer_thread_ = std::thread([this] { timer_loop(); });
    }

    void stop() {
        running_ = false;
        if (timer_thread_.joinable()) timer_thread_.join();
    }

    ReplicaId id() const { return id_; }
    bool is_primary() const { return id_ == view_ % n_; }
    int quorum() const { return 2 * f_ + 1; }
    View view() const { return view_; }

    void receive(const Message& m) {
        std::lock_guard<std::mutex> lk(mu_);
        last_activity_ = std::chrono::steady_clock::now();
        switch (m.type) {
            case MsgType::REQUEST:     on_request(m); break;
            case MsgType::PRE_PREPARE: on_pre_prepare(m); break;
            case MsgType::PREPARE:     on_prepare(m); break;
            case MsgType::COMMIT:      on_commit(m); break;
            case MsgType::VIEW_CHANGE: on_view_change(m); break;
            case MsgType::NEW_VIEW:    on_new_view(m); break;
            default: break;
        }
    }

    void client_request(const std::string& op) {
        std::lock_guard<std::mutex> lk(mu_);
        last_activity_ = std::chrono::steady_clock::now();
        Message m{MsgType::REQUEST, view_, 0, -1, digest(op), op, {}};
        on_request(m);
    }

    void set_byzantine(bool b) { byzantine_ = b; }
    bool is_byzantine() const { return byzantine_; }

private:
    ReplicaId id_;
    int f_, n_;
    std::vector<ReplicaId> all_;
    View view_;
    SeqNum seq_;

    std::mutex mu_;
    std::map<SeqNum, LogEntry> log_;
    bool byzantine_ = false;

    std::atomic<bool> running_{false};
    std::thread timer_thread_;
    std::chrono::steady_clock::time_point last_activity_;

    void log(const std::string& s) {
        std::lock_guard<std::mutex> lk(Network::get().cout_mu_);
        std::cout << "[R" << id_ << " v=" << view_ << "] " << s << "\n";
    }

    // =========================================================================
    // Phase 1: REQUEST → PRE-PREPARE (primary only)
    // =========================================================================
    // The primary assigns a sequence number and broadcasts to all replicas.
    // This establishes total order within a view.

    void on_request(const Message& m) {
        if (!is_primary()) {
            log("ignored REQUEST (not primary)");
            return;
        }
        SeqNum s = ++seq_;
        Message pp{MsgType::PRE_PREPARE, view_, s, id_, m.d, m.payload, {}};
        log_[s] = LogEntry{Phase::PRE_PREPARED, std::make_shared<Message>(pp), {}, {}, m.payload};
        log("PRIMARY: PRE-PREPARE s=" + std::to_string(s) + " op=\"" + m.payload + "\"");
        Network::get().broadcast(all_, pp, id_);
    }

    // =========================================================================
    // Phase 2: PRE-PREPARE → PREPARE
    // =========================================================================
    // Safety checks:
    //   1. Sender must be current primary (view_ % n_)
    //   2. View number must match
    //   3. Digest binds the message to the request
    // 
    // A replica is PREPARED when it has:
    //   - 1 PRE_PREPARE from primary
    //   - 2f matching PREPAREs from different replicas (including implicit self)
    //
    // Why 2f? Among 2f+1 replicas, at most f are Byzantine. So at least f+1
    // honest replicas have the request. This guarantees any future view
    // (with a different primary) will also see it.

    void on_pre_prepare(const Message& m) {
        if (m.sender != view_ % n_) {
            log("REJECT PRE-PREPARE: not from primary (sender=R" + std::to_string(m.sender) + ")");
            return;
        }
        if (m.view != view_) {
            log("REJECT PRE-PREPARE: view mismatch");
            return;
        }
        if (log_.count(m.seq)) return;

        log_[m.seq] = LogEntry{Phase::PRE_PREPARED, std::make_shared<Message>(m), {}, {}, m.payload};
        log("← PRE-PREPARE s=" + std::to_string(m.seq) + " → send PREPARE");

        Message p{MsgType::PREPARE, view_, m.seq, id_, m.d, "", {}};
        Network::get().broadcast(all_, p, id_);
    }

    void on_prepare(const Message& m) {
        if (m.view != view_) return;
        auto it = log_.find(m.seq);
        if (it == log_.end()) return;
        auto& e = it->second;

        // Byzantine check: digest must match our PRE-PREPARE
        if (!e.pre_prepare || m.d != e.pre_prepare->d) {
            log("REJECT PREPARE s=" + std::to_string(m.seq) + ": digest mismatch");
            return;
        }

        e.prepares.insert(m.sender);

        // Prepared when 2f matching PREPAREs received (others) + our own implicit
        if (e.phase == Phase::PRE_PREPARED && int(e.prepares.size()) >= 2 * f_) {
            e.phase = Phase::PREPARED;
            log("✓ PREPARED s=" + std::to_string(m.seq) + 
                " (" + std::to_string(e.prepares.size()) + " prepares)");

            Message c{MsgType::COMMIT, view_, m.seq, id_, m.d, "", {}};
            Network::get().broadcast(all_, c, id_);
        }
    }

    // =========================================================================
    // Phase 3: COMMIT
    // =========================================================================
    // After PREPARED, broadcast COMMIT. Committed when 2f+1 matching COMMITs.
    // This ensures that even if some replicas crash after preparing, enough
    // others have the request to guarantee execution in all views.

    void on_commit(const Message& m) {
        if (m.view != view_) return;
        auto it = log_.find(m.seq);
        if (it == log_.end()) return;
        auto& e = it->second;

        if (e.phase < Phase::PREPARED) return;
        if (m.d != e.pre_prepare->d) {
            log("REJECT COMMIT s=" + std::to_string(m.seq) + ": digest mismatch");
            return;
        }

        e.commits.insert(m.sender);

        if (e.phase == Phase::PREPARED && int(e.commits.size()) >= 2 * f_) {
            e.phase = Phase::COMMITTED;
            log("✓ COMMITTED s=" + std::to_string(m.seq) + 
                " (" + std::to_string(e.commits.size()) + " commits)");
            execute(m.seq, e.payload);
        }
    }

    // =========================================================================
    // Phase 4: EXECUTE
    // =========================================================================
    void execute(SeqNum s, const std::string& op) {
        log_[s].phase = Phase::EXECUTED;
        log("▶ EXECUTE s=" + std::to_string(s) + " op=\"" + op + "\"");
    }

    // =========================================================================
    // View Change (failure recovery)
    // =========================================================================
    // Triggered when:
    //   - Primary times out (no PRE-PREPARE for client's request)
    //   - Replica detects inconsistent state from primary (equivocation)
    // 
    // Protocol:
    //   1. Replica broadcasts VIEW_CHANGE for view v+1 (with prepared proofs)
    //   2. New primary (replica (v+1) mod n) collects 2f+1 VIEW_CHANGEs
    //   3. New primary broadcasts NEW_VIEW with the set of view changes
    //   4. Replicas verify NEW_VIEW and enter new view

    void on_view_change(const Message& m) {
        log("← VIEW-CHANGE from R" + std::to_string(m.sender) + " for view " + std::to_string(m.view));
    }

    void on_new_view(const Message& m) {
        log("← NEW-VIEW entering view " + std::to_string(m.view));
        view_ = m.view;
    }

    void trigger_view_change(const std::string& reason) {
        log("⚠ VIEW CHANGE triggered: " + reason);
        View nv = view_ + 1;
        Message vc{MsgType::VIEW_CHANGE, nv, 0, id_, "", "", {}};
        for (auto& [s, e] : log_) {
            if (e.phase >= Phase::PREPARED) {
                vc.prepared[s] = e.pre_prepare;
            }
        }
        Network::get().broadcast(all_, vc, id_);
        view_ = nv;
    }

    // =========================================================================
    // Timeout / Failure Detection
    // =========================================================================
    // Each replica runs a timer. If a request doesn't progress, the replica
    // suspects the primary is faulty and triggers a view change.

    void timer_loop() {
        while (running_) {
            std::this_thread::sleep_for(std::chrono::milliseconds(200));
            std::lock_guard<std::mutex> lk(mu_);
            auto now = std::chrono::steady_clock::now();
            auto elapsed = std::chrono::duration_cast<std::chrono::milliseconds>(
                now - last_activity_).count();

            // If we're not primary and haven't made progress, suspect primary
            if (!is_primary() && !log_.empty() && elapsed > 1000) {
                bool stuck = false;
                for (auto& [s, e] : log_) {
                    if (e.phase < Phase::COMMITTED) {
                        stuck = true;
                        break;
                    }
                }
                if (stuck) {
                    trigger_view_change("timeout: no progress for 1s");
                    last_activity_ = now;
                }
            }
        }
    }
};

