from typing import Optional

class Solver:
    def __init__(self, num_vars: int, clauses: list[list[int]]):
        self.num_vars = num_vars
        # Clauses as sets for fast lookup
        self.clauses = [set(c) for c in clauses]
        # Assignment: var -> True/False/None
        self.assign = [None] * (num_vars + 1)
        # Decision stack for backtracking
        self.decision_stack = []
        # Unit clauses to propagate
        self.unit_queue = []

    def solve(self) -> Optional[dict]:
        # Initialize unit queue with unit clauses
        for clause in self.clauses:
            if len(clause) == 1:
                lit = next(iter(clause))
                if not self._enqueue(lit):
                    return None
        # Unit propagation
        if not self._propagate():
            return None
        # Pure literal elimination
        self._pure_literal_elim()
        if not self._propagate():
            return None
        # DPLL
        if self._dpll():
            return {i: self.assign[i] for i in range(1, self.num_vars + 1)}
        return None

    def _lit_value(self, lit: int) -> Optional[bool]:
        """Evaluate literal under current assignment."""
        var = abs(lit)
        val = self.assign[var]
        if val is None:
            return None
        return val if lit > 0 else not val

    def _enqueue(self, lit: int) -> bool:
        """Assign variable to satisfy literal. Returns False if conflict."""
        var = abs(lit)
        val = lit > 0
        if self.assign[var] is None:
            self.assign[var] = val
            self.decision_stack.append((var, val, False))  # (var, val, is_decision)
            return True
        return self.assign[var] == val

    def _propagate(self) -> bool:
        """Unit propagation. Returns False if conflict."""
        # Find initial unit clauses
        for clause in self.clauses:
            unassigned = []
            satisfied = False
            for lit in clause:
                v = self._lit_value(lit)
                if v is True:
                    satisfied = True
                    break
                elif v is None:
                    unassigned.append(lit)
            if satisfied:
                continue
            if not unassigned:
                return False  # Conflict
            if len(unassigned) == 1:
                if not self._enqueue(unassigned[0]):
                    return False

        # Propagate
        changed = True
        while changed:
            changed = False
            for clause in self.clauses:
                unassigned = []
                satisfied = False
                for lit in clause:
                    v = self._lit_value(lit)
                    if v is True:
                        satisfied = True
                        break
                    elif v is None:
                        unassigned.append(lit)
                if satisfied:
                    continue
                if not unassigned:
                    return False
                if len(unassigned) == 1:
                    if not self._enqueue(unassigned[0]):
                        return False
                    changed = True
        return True

    def _pure_literal_elim(self) -> None:
        """Assign pure literals."""
        pos = set()
        neg = set()
        for clause in self.clauses:
            for lit in clause:
                if self._lit_value(lit) is None:
                    if lit > 0:
                        pos.add(lit)
                    else:
                        neg.add(abs(lit))
        for var in pos - {abs(l) for l in neg}:
            if self.assign[var] is None:
                self._enqueue(var)
        for var in neg - pos:
            if self.assign[var] is None:
                self._enqueue(-var)

    def _all_assigned(self) -> bool:
        return all(a is not None for a in self.assign[1:])

    def _choose_var(self) -> Optional[int]:
        for i in range(1, self.num_vars + 1):
            if self.assign[i] is None:
                return i
        return None

    def _dpll(self) -> bool:
        if self._all_assigned():
            return True
        var = self._choose_var()
        # Save state
        saved_assign = self.assign[:]
        saved_stack = self.decision_stack[:]
        # Try True
        self.decision_stack.append((var, True, True))
        self.assign[var] = True
        if self._propagate():
            self._pure_literal_elim()
            if self._propagate() and self._dpll():
                return True
        # Backtrack
        self.assign = saved_assign
        self.decision_stack = saved_stack
        # Try False
        self.decision_stack.append((var, False, True))
        self.assign[var] = False
        if self._propagate():
            self._pure_literal_elim()
            if self._propagate() and self._dpll():
                return True
        # Backtrack
        self.assign = saved_assign
        self.decision_stack = saved_stack
        return False


def solve_3sat(num_vars: int, clauses: list[list[int]]) -> Optional[dict]:
    solver = Solver(num_vars, clauses)
    return solver.solve()


