from typing import Optional

class Solver:
    def __init__(self, num_vars: int, clauses: list[list[int]]):
        self.num_vars = num_vars
        self.assign = [None] * (num_vars + 1)  # 1-indexed
        self.trail = []  # (var, old_value) for backtracking
        self.trail_markers = []  # stack of trail positions
        # Watched literals: for each literal, list of clause indices watching it
        self.watches = {}
        # For each clause, the two watched literals
        self.clause_watches = []
        self.clauses = clauses

        for i, clause in enumerate(clauses):
            if len(clause) == 1:
                self.clause_watches.append((clause[0], None))
            else:
                self.clause_watches.append((clause[0], clause[1]))
            for lit in clause[:2]:
                if lit not in self.watches:
                    self.watches[lit] = []
                self.watches[lit].append(i)

    def _lit_value(self, lit):
        var = abs(lit)
        v = self.assign[var]
        if v is None:
            return None
        return v if lit > 0 else not v

    def _assign(self, var, val, decision=False):
        if self.assign[var] is not None:
            return self.assign[var] == val
        self.assign[var] = val
        self.trail.append((var, None, decision))
        return True

    def _propagate(self):
        # Process newly assigned variables
        # We need to know which vars were just assigned
        # Use a queue of assigned vars
        queue = []
        in_queue = [False] * (self.num_vars + 1)
        for var in range(1, self.num_vars + 1):
            if self.assign[var] is not None:
                queue.append(var)
                in_queue[var] = True

        head = 0
        while head < len(queue):
            var = queue[head]
            head += 1
            val = self.assign[var]
            # The literal that just became false
            false_lit = -var if val else var
            # Check clauses watching false_lit
            if false_lit in self.watches:
                watches = list(self.watches[false_lit])
                for ci in watches:
                    w1, w2 = self.clause_watches[ci]
                    # Make sure false_lit is one of the watches
                    if w1 != false_lit and w2 != false_lit:
                        continue
                    other = w2 if w1 == false_lit else w1
                    # Check if other is satisfied
                    ov = self._lit_value(other)
                    if ov is True:
                        continue
                    # Try to find a new watch
                    clause = self.clauses[ci]
                    found = False
                    for lit in clause:
                        if lit != w1 and lit != w2:
                            lv = self._lit_value(lit)
                            if lv is not False:
                                # Update watches
                                if w1 == false_lit:
                                    self.clause_watches[ci] = (lit, w2)
                                else:
                                    self.clause_watches[ci] = (w1, lit)
                                # Remove from old watch list, add to new
                                self.watches[false_lit].remove(ci)
                                if lit not in self.watches:
                                    self.watches[lit] = []
                                self.watches[lit].append(ci)
                                found = True
                                break
                    if found:
                        continue
                    # No replacement found
                    if ov is None:
                        # Unit clause, must assign
                        if not self._assign(abs(other), other > 0):
                            return False
                        if not in_queue[abs(other)]:
                            queue.append(abs(other))
                            in_queue[abs(other)] = True
                    else:
                        # ov is False, conflict
                        return False
        return True
