"""
3-SAT Solver using DPLL with unit propagation and pure literal elimination.
"""

from typing import Optional


class SATSolver:
    """
    DPLL-based SAT solver.

    Literals are integers: positive = variable, negative = NOT variable.
    Variables are 1-indexed.
    """

    def __init__(self, num_vars: int, clauses: list[list[int]]):
        self.num_vars = num_vars
        self.clauses = [list(c) for c in clauses]
        # Assignment: 0 = unassigned, 1 = True, -1 = False
        self.assign = [0] * (num_vars + 1)
        # Trail for backtracking
        self.trail = []

    def solve(self) -> Optional[list[int]]:
        """Returns a satisfying assignment or None if unsatisfiable."""
        if self._dpll():
            return self.assign[1:]
        return None

    def _lit_value(self, lit: int) -> int:
        """Returns 1 if lit is true, -1 if false, 0 if unassigned."""
        v = self.assign[abs(lit)]
        if v == 0:
            return 0
        return v if lit > 0 else -v

    def _assign(self, var: int, val: int) -> bool:
        """Assign var=val. Returns False if conflict."""
        if self.assign[var] != 0:
            return self.assign[var] == val
        self.assign[var] = val
        self.trail.append(var)
        return True

    def _undo_until(self, marker: int) -> None:
        """Backtrack to trail position."""
        while len(self.trail) > marker:
            var = self.trail.pop()
            self.assign[var] = 0

    def _propagate(self) -> bool:
        """Unit propagation. Returns False if conflict detected."""
        changed = True
        while changed:
            changed = False
            for clause in self.clauses:
                # Evaluate clause
                unassigned_lit = None
                num_unassigned = 0
                satisfied = False
                for lit in clause:
                    val = self._lit_value(lit)
                    if val == 1:
                        satisfied = True
                        break
                    elif val == 0:
                        unassigned_lit = lit
                        num_unassigned += 1
                if satisfied:
                    continue
                if num_unassigned == 0:
                    return False  # Conflict
                if num_unassigned == 1:
                    # Unit clause - must assign
                    var = abs(unassigned_lit)
                    val = 1 if unassigned_lit > 0 else -1
                    if not self._assign(var, val):
                        return False
                    changed = True
        return True

    def _pure_literals(self) -> bool:
        """Eliminate pure literals. Returns False if conflict."""
        pos = set()
        neg = set()
        for clause in self.clauses:
            for lit in clause:
                if self._lit_value(lit) == 0:
                    if lit > 0:
                        pos.add(lit)
                    else:
                        neg.add(-lit)
        # Pure positive: assign True
        for var in pos - neg:
            if self.assign[var] == 0:
                if not self._assign(var, 1):
                    return False
        # Pure negative: assign False
        for var in neg - pos:
            if self.assign[var] == 0:
                if not self._assign(var, -1):
                    return False
        return True

    def _all_assigned(self) -> bool:
        return all(a != 0 for a in self.assign[1:])

    def _choose_var(self) -> int:
        """Choose next variable to branch on (first unassigned)."""
        for i in range(1, self.num_vars + 1):
            if self.assign[i] == 0:
                return i
        return -1

    def _dpll(self) -> bool:
        if self._all_assigned():
            return True

        # Pure literal elimination
        if not self._pure_literals():
            return False
        if not self._propagate():
            return False
        if self._all_assigned():
            return True

        var = self._choose_var()

        # Try var = True
        marker = len(self.trail)
        self._assign(var, 1)
        if self._propagate() and self._dpll():
            return True
        self._undo_until(marker)

        # Try var = False
        marker = len(self.trail)
        self._assign(var, -1)
        if self._propagate() and self._dpll():
            return True
        self._undo_until(marker)

        return False


def solve_sat(num_vars: int, clauses: list[list[int]]) -> Optional[list[int]]:
    """Solve a SAT instance. Returns satisfying assignment or None."""
    solver = SATSolver(num_vars, clauses)
    return solver.solve()


# Example usage
if __name__ == "__main__":
    # (x1 ∨ x2 ∨ x3) ∧ (¬x1 ∨ x2 ∨ x3) ∧ (x1 ∨ ¬x2 ∨ x3) ∧ (¬x1 ∨ ¬x2 ∨ x3)
    clauses = [
        [1, 2, 3],
        [-1, 2, 3],
        [1, -2, 3],
        [-1, -2, 3],
    ]
    result = solve_sat(3, clauses)
    print("Satisfiable:", result is not None)
    if result:
        print("Assignment:", result)

    # Unsatisfiable example: (x) ∧ (¬x)
    clauses2 = [[1], [-1]]
    result2 = solve_sat(1, clauses2)
    print("Satisfiable:", result2 is not None)
