class SATSolver:
    def __init__(self, num_vars, clauses):
        self.num_vars = num_vars
        self.assign = [0] * (num_vars + 1)
        self.trail = []
        self.clauses = clauses
        # For each clause, store the two watched literals
        self.w1 = []
        self.w2 = []
        # For each literal, list of clause indices watching it
        self.watch_list = {}

        for i, clause in enumerate(clauses):
            if len(clause) == 1:
                self.w1.append(clause[0])
                self.w2.append(0)  # sentinel
            else:
                self.w1.append(clause[0])
                self.w2.append(clause[1])
            for lit in [self.w1[-1], self.w2[-1]] if self.w2[-1] != 0 else [self.w1[-1]]:
                self.watch_list.setdefault(lit, []).append(i)

    def _lit_value(self, lit):
        if lit == 0:
            return 1  # sentinel is "true"
        v = self.assign[abs(lit)]
        if v == 0:
            return 0
        return v if lit > 0 else -v

    def _assign(self, var, val):
        if self.assign[var] != 0:
            return self.assign[var] == val
        self.assign[var] = val
        self.trail.append(var)
        return True

    def _undo_until(self, marker):
        while len(self.trail) > marker:
            self.assign[self.trail.pop()] = 0

    def _propagate(self):
        # Propagate all newly assigned variables
        # We need to know which vars were assigned since last call
        # Use a propagation queue
        prop_queue = []
        for var in self.trail:
            prop_queue.append(var)

        qi = 0
        while qi < len(prop_queue):
            var = prop_queue[qi]
            qi += 1
            val = self.assign[var]
            # The literal that just became false
            false_lit = var if val == -1 else -var

            if false_lit not in self.watch_list:
                continue

            watches = self.watch_list[false_lit][:]
            for ci in watches:
                w1, w2 = self.w1[ci], self.w2[ci]
                # Make sure false_lit is one of the watches
                if w1 != false_lit and w2 != false_lit:
                    continue

                # Try other watch first
                other = w2 if w1 == false_lit else w1
                ov = self._lit_value(other)
                if ov == 1:
                    continue

                # Try to find replacement
                clause = self.clauses[ci]
                found = False
                for lit in clause:
                    if lit != w1 and lit != w2:
                        lv = self._lit_value(lit)
                        if lv != -1:
                            # Update watch
                            if w1 == false_lit:
                                self.w1[ci] = lit
                            else:
                                self.w2[ci] = lit
                            # Move watch
                            self.watch_list[false_lit].remove(ci)
                            self.watch_list.setdefault(lit, []).append(ci)
                            found = True
                            break
                if found:
                    continue

                # No replacement
                if ov == 0:
                    # Unit clause
                    if not self._assign(abs(other), 1 if other > 0 else -1):
                        return False
                    prop_queue.append(abs(other))
                else:
                    # ov == -1, conflict
                    return False
        return True
