"""
3-SAT Solver using DPLL with unit propagation and pure literal elimination.

Usage:
    solver = SATSolver(num_vars, clauses)
    result = solver.solve()
    if result is not None:
        print("SAT:", result)
    else:
        print("UNSAT")
"""

from typing import Optional


class SATSolver:
    """
    DPLL-based SAT solver.

    Representation:
        - Literals: positive int = variable, negative int = NOT variable
        - Variables: 1-indexed
        - Assignment: 0 = unassigned, 1 = True, -1 = False
    """

    def __init__(self, num_vars: int, clauses: list[list[int]]):
        self.num_vars = num_vars
        self.clauses = clauses
        self.assign = [0] * (num_vars + 1)
        self.trail = []  # Stack of assigned variables for backtracking

    def solve(self) -> Optional[list[int]]:
        """Returns a satisfying assignment, or None if unsatisfiable."""
        if self._dpll():
            return self.assign[1:]
        return None

    # --- Literal evaluation ---

    def _val(self, lit: int) -> int:
        """Evaluate literal: 1 if true, -1 if false, 0 if unassigned."""
        a = self.assign[abs(lit)]
        if a == 0:
            return 0
        return a if lit > 0 else -a

    # --- Assignment with trail ---

    def _set(self, var: int, val: int) -> bool:
        """Assign var=val. Returns False on conflict."""
        if self.assign[var] != 0:
            return self.assign[var] == val
        self.assign[var] = val
        self.trail.append(var)
        return True

    def _undo(self, marker: int) -> None:
        """Undo assignments back to trail position `marker`."""
        while len(self.trail) > marker:
            self.assign[self.trail.pop()] = 0

    # --- Unit propagation ---

    def _propagate(self) -> bool:
        """
        Repeatedly find unit clauses and assign them.
        Returns False if a conflict is detected.
        """
        changed = True
        while changed:
            changed = False
            for clause in self.clauses:
                sat = False
                last_unassigned = None
                num_unassigned = 0
                for lit in clause:
                    v = self._val(lit)
                    if v == 1:
                        sat = True
                        break
                    if v == 0:
                        num_unassigned += 1
                        last_unassigned = lit
                if sat:
                    continue
                if num_unassigned == 0:
                    return False  # All false -> conflict
                if num_unassigned == 1:
                    # Unit clause: force the remaining literal true
                    var = abs(last_unassigned)
                    val = 1 if last_unassigned > 0 else -1
                    if not self._set(var, val):
                        return False
                    changed = True
        return True

    # --- Pure literal elimination ---

    def _pure_elim(self) -> bool:
        """
        Find variables that appear with only one polarity and assign them.
        Returns False on conflict.
        """
        pos = set()
        neg = set()
        for clause in self.clauses:
            for lit in clause:
                if self._val(lit) == 0:
                    if lit > 0:
                        pos.add(lit)
                    else:
                        neg.add(-lit)
        for var in pos - neg:
            if not self._set(var, 1):
                return False
        for var in neg - pos:
            if not self._set(var, -1):
                return False
        return True

    # --- DPLL recursion ---

    def _dpll(self) -> bool:
        # Reduce
        if not self._pure_elim():
            return False
        if not self._propagate():
            return False

        # Check if all assigned
        if all(a != 0 for a in self.assign[1:]):
            return True

        # Choose a variable (first unassigned)
        var = next(i for i in range(1, self.num_vars + 1) if self.assign[i] == 0)

        # Branch: try True
        marker = len(self.trail)
        self._set(var, 1)
        if self._dpll():
            return True
        self._undo(marker)

        # Branch: try False
        marker = len(self.trail)
        self._set(var, -1)
        if self._dpll():
            return True
        self._undo(marker)

        return False


def solve_sat(num_vars: int, clauses: list[list[int]]) -> Optional[list[int]]:
    """Convenience function to solve a SAT instance."""
    return SATSolver(num_vars, clauses).solve()


def parse_dimacs(text: str) -> tuple[int, list[list[int]]]:
    """Parse a DIMACS CNF file."""
    num_vars = 0
    clauses = []
    for line in text.split('\n'):
        line = line.strip()
        if not line or line.startswith('c') or line.startswith('0'):
            continue
        if line.startswith('p'):
            parts = line.split()
            num_vars = int(parts[2])
            continue
        lits = [int(x) for x in line.split() if x != '0']
        if lits:
            clauses.append(lits)
    return num_vars, clauses


# --- Demo ---
