    clauses = [[1, 2, 3], [-1, 2, 3], [1, -2, 3], [-1, -2, 3]]
    result = solve_sat(3, clauses)
    print("Test 1:", "SAT" if result else "UNSAT", result)

    # Unsatisfiable: (x1) ∧ (¬x1)
