from typing import Optional
from collections import defaultdict


class SATSolver:
    def __init__(self, num_vars: int, clauses: list[list[int]]):
        self.num_vars = num_vars
        self.clauses = clauses
        self.assign = [0] * (num_vars + 1)
        self.trail = []

        # Watched literals: each clause watches 2 literals
        self.watch = [[0, 0] for _ in clauses]  # [w1, w2] per clause
        self.watch_list = defaultdict(list)  # lit -> [clause indices]

        for ci, clause in enumerate(clauses):
            if len(clause) == 1:
                self.watch[ci] = [clause[0], 0]
                self.watch_list[clause[0]].append(ci)
            else:
                self.watch[ci] = [clause[0], clause[1]]
                self.watch_list[clause[0]].append(ci)
                self.watch_list[clause[1]].append(ci)

    def solve(self) -> Optional[list[int]]:
        if self._dpll():
            return self.assign[1:]
        return None

    def _val(self, lit: int) -> int:
        if lit == 0:
            return 1  # sentinel
        a = self.assign[abs(lit)]
        if a == 0:
            return 0
        return a if lit > 0 else -a

    def _set(self, var: int, val: int) -> bool:
        if self.assign[var] != 0:
            return self.assign[var] == val
        self.assign[var] = val
        self.trail.append(var)
        return True

    def _undo(self, marker: int) -> None:
        while len(self.trail) > marker:
            self.assign[self.trail.pop()] = 0

    def _propagate(self) -> bool:
        """Unit propagation using watched literals."""
        # Propagate all variables assigned since last call
        # We track which vars to process via the trail
        start = self._prop_marker
        self._prop_marker = len(self.trail)

        for idx in range(start, self._prop_marker):
            var = self.trail[idx]
            val = self.assign[var]
            # The literal that just became false
            false_lit = -var if val == 1 else var

            watches = self.watch_list[false_lit]
            i = 0
            while i < len(watches):
                ci = watches[i]
                w1, w2 = self.watch[ci]

                # Skip if this clause isn't actually watching false_lit
                if w1 != false_lit and w2 != false_lit:
                    i += 1
                    continue

                # The other watch
                other = w2 if w1 == false_lit else w1
                ov = self._val(other)
                if ov == 1:
                    i += 1
                    continue

                # Try to find a replacement watch
                clause = self.clauses[ci]
                found = False
                for lit in clause:
                    if lit != w1 and lit != w2:
                        lv = self._val(lit)
                        if lv != -1:
                            # Replace watch
