    # UNSAT: (x1) ∧ (¬x1)
    r = solve_sat(1, [[1],[-1]])
    print("Test 2:", "SAT" if r else "UNSAT", r)

    # Pigeonhole(3,2): UNSAT
    ph = []
    for i in range(3):
