    for i in range(3):
        for j in range(i+1, 3):
            ph.append([-(2*i+1), -(2*j+1)])
            ph.append([-(2*i+2), -(2*j+2)])
    r = solve_sat(6, ph)
    print("Pigeonhole(3,2):", "SAT" if r else "UNSAT")
