# Minimal Perfect Hash Map in Rust

Here's a complete implementation using the **FCH (Fox, Chen, Heath) algorithm** — one of the simplest and most elegant approaches to building a minimal perfect hash function (MPHF).

## How the Algorithm Works

The idea is beautifully simple:

1. Pick two hash functions `h1`, `h2` parameterized by a seed.
2. For each key `k`, compute two candidate slots: `h1(k) mod n` and `h2(k) mod n`.
3. Build a **bipartite graph**: keys on one side, slots `[0, n)` on the other. Each key connects to its two candidate slots.
4. Find a **perfect matching** using augmenting paths (Kuhn's algorithm).
5. If no perfect matching exists, try a different seed.

Lookup is O(1): compute both hashes, check both slots.

## The Code

Save this as `src/lib.rs`:

```rust
//! Minimal perfect hash function and hash map using the FCH algorithm.

use std::hash::{Hash, Hasher};
use std::collections::hash_map::DefaultHasher;

/// A minimal perfect hash function for a fixed set of keys.
///
/// Given `n` keys, produces a bijection from the keys to `[0, n)`.
/// Lookup is O(1) with at most 2 hash computations and 2 comparisons.
///
/// # Algorithm (FCH: Fox, Chen, Heath)
///
/// 1. Pick two hash functions `h1`, `h2` parameterized by a seed.
/// 2. For each key, compute candidate slots `h1(k) % n` and `h2(k) % n`.
/// 3. Build a bipartite graph: keys ↔ slots, each key connected to its
///    two candidate slots.
/// 4. Find a perfect matching using augmenting paths.
/// 5. If no perfect matching exists, try a different seed.
#[derive(Debug)]
pub struct MinimalPerfectHash<K> {
    /// `keys[slot]` is the key assigned to that slot.
    keys: Vec<K>,
    /// Seed parameterizing the hash functions.
    seed: u64,
}

impl<K: Hash + Eq + Clone> MinimalPerfectHash<K> {
    /// Build a minimal perfect hash for the given keys.
    ///
    /// # Panics
    /// Panics if the key set is empty, or if no seed (out of 10,000
    /// tried) yields a perfect matching — extremely unlikely for `n ≥ 2`.
    pub fn new(keys: Vec<K>) -> Self {
        let n = keys.len();
        assert!(n > 0, "Cannot build perfect hash for empty set");

        // Try seeds until we find one that produces a perfect matching.
        let seed = (0..10_000u64)
            .find(|&seed| Self::can_build(&keys, n, seed))
            .expect("Failed to build minimal perfect hash after 10,000 attempts");

        // Build the assignment and reorder keys by slot.
        let assignment = Self::build_assignment(&keys, n, seed);
        let mut ordered: Vec<Option<K>> = (0..n).map(|_| None).collect();
        for (key_idx, &slot) in assignment.iter().enumerate() {
            ordered[slot] = Some(keys[key_idx].clone());
        }

        MinimalPerfectHash {
            keys: ordered.into_iter().map(|x| x.unwrap()).collect(),
            seed,
        }
    }

    /// Returns the slot for `key`, or `None` if the key is not in the set.
    #[inline]
    pub fn get_index(&self, key: &K) -> Option<usize> {
        let n = self.keys.len();
        let h1 = hash1(key, self.seed) % n;
        let h2 = hash2(key, self.seed) % n;

        if self.keys[h1] == *key {
            Some(h1)
        } else if self.keys[h2] == *key {
            Some(h2)
        } else {
            None
        }
    }

    /// Returns the slot for `key`. Panics if not found.
    #[inline]
    pub fn index(&self, key: &K) -> usize {
        self.get_index(key).expect("Key not found in perfect hash")
    }

    pub fn len(&self) -> usize {
        self.keys.len()
    }

    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }

    // ---- Internal: bipartite matching ----

    /// Check whether `seed` yields a perfect matching.
    fn can_build(keys: &[K], n: usize, seed: u64) -> bool {
        let candidates = Self::compute_candidates(keys, n, seed);
        let mut match_slot: Vec<Option<usize>> = vec![None; n];

        for key in 0..n {
            let mut visited = vec![false; n];
            if !Self::dfs(key, &candidates, &mut match_slot, &mut visited) {
                return false;
            }
        }
        true
    }

    /// Build the full `key_idx → slot` assignment.
    fn build_assignment(keys: &[K], n: usize, seed: u64) -> Vec<usize> {
        let candidates = Self::compute_candidates(keys, n, seed);
        let mut match_slot: Vec<Option<usize>> = vec![None; n];

        for key in 0..n {
            let mut visited = vec![false; n];
            assert!(
                Self::dfs(key, &candidates, &mut match_slot, &mut visited),
                "Perfect matching should exist (checked by can_build)"
            );
        }

        // Invert: match_slot[slot] = key  →  assignment[key] = slot
        let mut assignment = vec![0usize; n];
        for slot in 0..n {
            if let Some(key) = match_slot[slot] {
                assignment[key] = slot;
            }
        }
        assignment
    }

    #[inline]
    fn compute_candidates(keys: &[K], n: usize, seed: u64) -> Vec<(usize, usize)> {
        keys.iter()
            .map(|k| (hash1(k, seed) % n, hash2(k, seed) % n))
            .collect()
    }

    /// Kuhn's algorithm: DFS to find an augmenting path from `key`
    /// to a free slot.
    fn dfs(
        key: usize,
        candidates: &[(usize, usize)],
        match_slot: &mut [Option<usize>],
        visited: &mut [bool],
    ) -> bool {
        let (h1, h2) = candidates[key];
        for &slot in &[h1, h2] {
            if visited[slot] {
                continue;
            }
            visited[slot] = true;

            match match_slot[slot] {
                None => {
                    // Free slot — claim it.
                    match_slot[slot] = Some(key);
                    return true;
                }
                Some(other) => {
                    // Slot is taken; try to displace the key holding it.
                    if Self::dfs(other, candidates, match_slot, visited) {
                        match_slot[slot] = Some(key);
                        return true;
                    }
                }
            }
        }
        false
    }
}

// ---- Hash functions ----
//
// We use Rust's `DefaultHasher` (SipHash-1-3) with two different seeds
// to get two "independent" hash functions. Inverting the seed for h2
// guarantees they differ even when seed == 0.

#[inline]
fn hash1<K: Hash>(key: &K, seed: u64) -> usize {
    let mut h = DefaultHasher::new();
    seed.hash(&mut h);
    key.hash(&mut h);
    h.finish() as usize
}

#[inline]
fn hash2<K: Hash>(key: &K, seed: u64) -> usize {
    let mut h = DefaultHasher::new();
    (!seed).hash(&mut h);
    key.hash(&mut h);
    h.finish() as usize
}

// ---------------------------------------------------------------------------
//  PerfectHashMap — a hash map backed by the MPHF
// ---------------------------------------------------------------------------

/// A hash map backed by a minimal perfect hash function.
///
/// O(1) lookup, no collision handling. More space-efficient than
/// `std::collections::HashMap` for large, fixed key sets because it
/// needs no buckets and no collision lists.
#[derive(Debug)]
pub struct PerfectHashMap<K, V> {
    keys: Vec<K>,
    values: Vec<V>,
    seed: u64,
}

impl<K: Hash + Eq + Clone, V> PerfectHashMap<K, V> {
    /// Build a perfect hash map from key-value pairs.
    pub fn new(pairs: Vec<(K, V)>) -> Self {
        let n = pairs.len();
        let orig_keys: Vec<K> = pairs.iter().map(|(k, _)| k.clone()).collect();
        let orig_values: Vec<V> = pairs.into_iter().map(|(_, v)| v).collect();

        // Build the MPHF to discover the seed.
        let mph = MinimalPerfectHash::new(orig_keys.clone());
        let seed = mph.seed;

        // Reorder keys and values so that index == slot.
        let mut keys_by_slot: Vec<Option<K>> = (0..n).map(|_| None).collect();
        let mut vals_by_slot: Vec<Option<V>> = (0..n).map(|_| None).collect();
        for (i, key) in orig_keys.iter().enumerate() {
            let slot = mph.get_index(key).expect("key must be in MPH");
            keys_by_slot[slot] = Some(key.clone());
            vals_by_slot[slot] = Some(orig_values[i].clone());
        }

        PerfectHashMap {
            keys: keys_by_slot.into_iter().map(|x| x.unwrap()).collect(),
            values: vals_by_slot.into_iter().map(|x| x.unwrap()).collect(),
            seed,
        }
    }

    /// Look up a value by key.
    #[inline]
    pub fn get(&self, key: &K) -> Option<&V> {
        let n = self.keys.len();
        let h1 = hash1(key, self.seed) % n;
        let h2 = hash2(key, self.seed) % n;

        if self.keys[h1] == *key {
            Some(&self.values[h1])
        } else if self.keys[h2] == *key {
            Some(&self.values[h2])
        } else {
            None
        }
    }

    pub fn len(&self) -> usize {
        self.keys.len()
    }

    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }
}

