mod tests {
    use super::*;

    #[test]
    fn basic_string_keys() {
        let keys = vec!["apple", "banana", "cherry", "date", "elderberry"];
        let mph = MinimalPerfectHash::new(keys);

        // Every key maps to a unique slot in [0, 5).
        let all = ["apple", "banana", "cherry", "date", "elderberry"];
        let mut slots: Vec<usize> = all.iter().map(|k| mph.index(k)).collect();
        slots.sort();
        assert_eq!(slots, vec![0, 1, 2, 3, 4]);

        // Unknown key → None.
        assert_eq!(mph.get_index(&"grape"), None);
    }

    #[test]
    fn single_key() {
        let mph = MinimalPerfectHash::new(vec!["only"]);
        assert_eq!(mph.get_index(&"only"), Some(0));
        assert_eq!(mph.get_index(&"other"), None);
    }

    #[test]
    fn integer_keys() {
        let mph = MinimalPerfectHash::new(vec![10, 20, 30, 40, 50]);
        for &k in &[10, 20, 30, 40, 50] {
            assert!(mph.get_index(&k).is_some());
        }
        assert_eq!(mph.get_index(&99), None);
    }

    #[test]
    fn hash_map_lookup() {
        let map = PerfectHashMap::new(vec![
            ("apple", 1),
            ("banana", 2),
            ("cherry", 3),
        ]);
        assert_eq!(map.get(&"apple"), Some(&1));
        assert_eq!(map.get(&"banana"), Some(&2));
        assert_eq!(map.get(&"cherry"), Some(&3));
        assert_eq!(map.get(&"grape"), None);
    }

    #[test]
    fn large_set() {
        let keys: Vec<String> = (0..1000).map(|i| format!("key_{}", i)).collect();
        let mph = MinimalPerfectHash::new(keys);

        // All 1000 keys must be found, each at a unique slot.
        let mut slots: Vec<usize> = (0..1000)
            .map(|i| mph.index(&format!("key_{}", i)))
            .collect();
        slots.sort();
        assert_eq!(slots, (0..1000).collect::<Vec<_>>());

        assert_eq!(mph.get_index(&"key_9999"), None);
    }
}
