use std::hash::{Hash, Hasher};
use std::collections::hash_map::DefaultHasher;

/// A minimal perfect hash function for a fixed set of keys.
///
/// Uses the FCH (Fox, Chen, Heath) algorithm with two hash functions
/// and bipartite matching.
pub struct MinimalPerfectHash<K> {
    keys: Vec<K>,
    seed: u64,
}

impl<K: Hash + Eq + Clone> MinimalPerfectHash<K> {
    /// Build a minimal perfect hash for the given keys.
    pub fn new(keys: Vec<K>) -> Self {
        let n = keys.len();
        assert!(n > 0, "Cannot build perfect hash for empty set");

        // Try different seeds until we find one that produces a perfect matching
        for seed in 0..1000 {
            if Self::try_build(&keys, n, seed).is_some() {
                return MinimalPerfectHash {
                    keys,
                    seed,
                };
            }
        }

        panic!("Failed to build minimal perfect hash after 1000 attempts");
    }

    fn try_build(keys: &[K], n: usize, seed: u64) -> Option<Vec<usize>> {
        // Compute candidate slots for each key
        let candidates: Vec<(usize, usize)> = keys.iter()
            .map(|k| {
                let h1 = hash1(k, seed) % n;
                let h2 = hash2(k, seed) % n;
                (h1, h2)
            })
            .collect();

        // Find a perfect matching using augmenting paths
        let mut match_slot: Vec<Option<usize>> = vec![None; n];

        for key in 0..n {
            let mut visited = vec![false; n];
            if !Self::dfs(key, &candidates, &mut match_slot, &mut visited) {
                return None;
            }
        }

        // Extract assignment
        let mut assignment = vec![0; n];
        for slot in 0..n {
            if let Some(key) = match_slot[slot] {
                assignment[key] = slot;
            }
        }
        Some(assignment)
    }

    fn dfs(
        key: usize,
        candidates: &[(usize, usize)],
        match_slot: &mut [Option<usize>],
        visited: &mut [bool],
    ) -> bool {
        let (h1, h2) = candidates[key];
        for &slot in &[h1, h2] {
            if visited[slot] {
                continue;
            }
            visited[slot] = true;

            if match_slot[slot].is_none() {
                match_slot[slot] = Some(key);
                return true;
            } else if Self::dfs(match_slot[slot].unwrap(), candidates, match_slot, visited) {
                match_slot[slot] = Some(key);
                return true;
            }
        }
        false
    }

    /// Get the index for a key. Returns None if the key is not in the set.
    pub fn get_index(&self, key: &K) -> Option<usize> {
        let n = self.keys.len();
        let h1 = hash1(key, self.seed) % n;
        let h2 = hash2(key, self.seed) % n;

        if self.keys[h1] == *key {
            Some(h1)
        } else if self.keys[h2] == *key {
            Some(h2)
        } else {
            None
        }
    }

    /// Get the index for a key, panicking if not found.
    pub fn index(&self, key: &K) -> usize {
        self.get_index(key).expect("Key not found")
    }
}

fn hash1<K: Hash>(key: &K, seed: u64) -> usize {
    let mut hasher = DefaultHasher::new();
    seed.hash(&mut hasher);
    key.hash(&mut hasher);
    hasher.finish() as usize
}

fn hash2<K: Hash>(key: &K, seed: u64) -> usize {
    let mut hasher = DefaultHasher::new();
    (!seed).hash(&mut hasher);
    key.hash(&mut hasher);
    hasher.finish() as usize
}
