fn hash1<K: Hash>(key: &K, seed: u64) -> usize {
    let mut hasher = DefaultHasher::new();
    seed.hash(&mut hasher);
    key.hash(&mut hasher);
    hasher.finish() as usize
}

#[inline]
fn hash2<K: Hash>(key: &K, seed: u64) -> usize {
    let mut hasher = DefaultHasher::new();
    (!seed).hash(&mut hasher);
    key.hash(&mut hasher);
    hasher.finish() as usize
}

/// A hash map backed by a minimal perfect hash function.
///
/// Provides O(1) lookup with no collision handling. More space-efficient
/// than `std::collections::HashMap` for large, fixed key sets because
/// it doesn't need to store hash buckets or handle collisions.
///
/// # Example
///
/// ```
/// use perfect_hash::PerfectHashMap;
/// let map = PerfectHashMap::new(vec![
///     ("apple", 1),
///     ("banana", 2),
///     ("cherry", 3),
/// ]);
/// assert_eq!(map.get(&"banana"), Some(&2));
/// assert_eq!(map.get(&"grape"), None);
/// ```
#[derive(Debug)]
pub struct PerfectHashMap<K, V> {
    keys: Vec<K>,
    values: Vec<V>,
    seed: u64,
}

impl<K: Hash + Eq + Clone, V> PerfectHashMap<K, V> {
    /// Build a perfect hash map from a vector of key-value pairs.
    pub fn new(pairs: Vec<(K, V)>) -> Self {
        let n = pairs.len();
        let original_keys: Vec<K> = pairs.iter().map(|(k, _)| k.clone()).collect();
        let original_values: Vec<V> = pairs.into_iter().map(|(_, v)| v).collect();

        let mph = MinimalPerfectHash::new(original_keys.clone());
        let seed = mph.seed;

        let mut keys_by_slot: Vec<Option<K>> = (0..n).map(|_| None).collect();
        let mut values_by_slot: Vec<Option<V>> = (0..n).map(|_| None).collect();
        for (key_idx, key) in original_keys.iter().enumerate() {
            let slot = mph.get_index(key).expect("Key should be in MPH");
            keys_by_slot[slot] = Some(key.clone());
            values_by_slot[slot] = Some(original_values[key_idx].clone());
        }

        PerfectHashMap {
            keys: keys_by_slot.into_iter().map(|x| x.unwrap()).collect(),
            values: values_by_slot.into_iter().map(|x| x.unwrap()).collect(),
            seed,
        }
    }

    /// Get the value for a key.
    #[inline]
    pub fn get(&self, key: &K) -> Option<&V> {
        let n = self.keys.len();
        let h1 = hash1(key, self.seed) % n;
        let h2 = hash2(key, self.seed) % n;

        if self.keys[h1] == *key {
            Some(&self.values[h1])
        } else if self.keys[h2] == *key {
            Some(&self.values[h2])
        } else {
            None
        }
    }

    /// Returns the number of key-value pairs.
    pub fn len(&self) -> usize {
        self.keys.len()
    }

    /// Returns true if the map is empty.
    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }
}

