//! Minimal perfect hash function and hash map using the FCH algorithm.

use std::hash::{Hash, Hasher};
use std::collections::hash_map::DefaultHasher;

/// A minimal perfect hash function for a fixed set of keys.
///
/// Given a set of `n` keys, this produces a bijection from the keys to
/// `[0, n)`. Lookup is O(1) with at most 2 hash computations and 2
/// equality comparisons.
///
/// # Algorithm
///
/// Uses the FCH (Fox, Chen, Heath) algorithm:
/// 1. Pick two hash functions `h1`, `h2` parameterized by a seed.
/// 2. For each key, compute candidate slots `h1(k) mod n` and `h2(k) mod n`.
/// 3. Build a bipartite graph: keys on one side, slots on the other.
///    Each key is connected to its two candidate slots.
/// 4. Find a perfect matching using augmenting paths.
/// 5. If no perfect matching exists, try a different seed.
///
/// # Example
///
/// ```
/// use perfect_hash::MinimalPerfectHash;
/// let keys = vec!["apple", "banana", "cherry"];
/// let mph = MinimalPerfectHash::new(keys);
/// assert!(mph.get_index(&"banana").is_some());
/// assert_eq!(mph.get_index(&"grape"), None);
/// ```
#[derive(Debug)]
pub struct MinimalPerfectHash<K> {
    /// Keys indexed by their assigned slot.
    keys: Vec<K>,
    /// Seed for the hash functions.
    seed: u64,
}

impl<K: Hash + Eq + Clone> MinimalPerfectHash<K> {
    /// Build a minimal perfect hash for the given keys.
    ///
    /// # Panics
    ///
    /// Panics if the key set is empty or if a perfect hash cannot be
    /// found after 10,000 seed attempts (extremely unlikely for
    /// reasonable key sets with n ≥ 2).
    pub fn new(keys: Vec<K>) -> Self {
        let n = keys.len();
        assert!(n > 0, "Cannot build perfect hash for empty set");

        // Try seeds until we find one that produces a perfect matching
        let seed = (0..10_000)
            .find(|&seed| Self::can_build(&keys, n, seed))
            .expect("Failed to build minimal perfect hash after 10,000 attempts");

        // Build the assignment and reorder keys by slot
        let assignment = Self::build_assignment(&keys, n, seed);
        let mut ordered_keys: Vec<Option<K>> = (0..n).map(|_| None).collect();
        for (key_idx, &slot) in assignment.iter().enumerate() {
            ordered_keys[slot] = Some(keys[key_idx].clone());
        }

        MinimalPerfectHash {
            keys: ordered_keys.into_iter().map(|x| x.unwrap()).collect(),
            seed,
        }
    }

    /// Returns the slot for `key`, or `None` if the key is not in the set.
    #[inline]
    pub fn get_index(&self, key: &K) -> Option<usize> {
        let n = self.keys.len();
        let h1 = hash1(key, self.seed) % n;
        let h2 = hash2(key, self.seed) % n;

        if self.keys[h1] == *key {
            Some(h1)
        } else if self.keys[h2] == *key {
            Some(h2)
        } else {
            None
        }
    }

    /// Returns the slot for `key`. Panics if the key is not in the set.
    #[inline]
    pub fn index(&self, key: &K) -> usize {
        self.get_index(key).expect("Key not found in perfect hash")
    }

    /// Returns the number of keys.
    pub fn len(&self) -> usize {
        self.keys.len()
    }

    /// Returns true if the set is empty.
    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }

    // --- Internal methods ---

    /// Check if a seed produces a valid perfect matching.
    fn can_build(keys: &[K], n: usize, seed: u64) -> bool {
        let candidates = Self::compute_candidates(keys, n, seed);
        let mut match_slot: Vec<Option<usize>> = vec![None; n];

        for key in 0..n {
            let mut visited = vec![false; n];
            if !Self::dfs(key, &candidates, &mut match_slot, &mut visited) {
                return false;
            }
        }
        true
    }

    /// Build the full assignment (key_idx -> slot).
    fn build_assignment(keys: &[K], n: usize, seed: u64) -> Vec<usize> {
        let candidates = Self::compute_candidates(keys, n, seed);
        let mut match_slot: Vec<Option<usize>> = vec![None; n];

        for key in 0..n {
            let mut visited = vec![false; n];
            assert!(
                Self::dfs(key, &candidates, &mut match_slot, &mut visited),
                "Perfect matching should exist (checked by can_build)"
            );
        }

        let mut assignment = vec![0; n];
        for slot in 0..n {
            if let Some(key) = match_slot[slot] {
                assignment[key] = slot;
            }
        }
        assignment
    }

    /// Compute candidate slots for each key.
    #[inline]
    fn compute_candidates(keys: &[K], n: usize, seed: u64) -> Vec<(usize, usize)> {
        keys.iter()
            .map(|k| {
                let h1 = hash1(k, seed) % n;
                let h2 = hash2(k, seed) % n;
                (h1, h2)
            })
            .collect()
    }

    /// DFS to find augmenting paths in the bipartite graph.
    fn dfs(
        key: usize,
        candidates: &[(usize, usize)],
        match_slot: &mut [Option<usize>],
        visited: &mut [bool],
    ) -> bool {
        let (h1, h2) = candidates[key];
        for &slot in &[h1, h2] {
            if visited[slot] {
                continue;
            }
            visited[slot] = true;

            match match_slot[slot] {
                None => {
                    match_slot[slot] = Some(key);
                    return true;
                }
                Some(other_key) => {
                    if Self::dfs(other_key, candidates, match_slot, visited) {
                        match_slot[slot] = Some(key);
                        return true;
                    }
                }
            }
        }
        false
    }
}

/// First hash function: hash with seed.
#[inline]
fn hash1<K: Hash>(key: &K, seed: u64) -> usize {
    let mut hasher = DefaultHasher::new();
    seed.hash(&mut hasher);
    key.hash(&mut hasher);
    hasher.finish() as usize
}

/// Second hash function: hash with inverted seed for independence.
#[inline]
fn hash2<K: Hash>(key: &K, seed: u64) -> usize {
    let mut hasher = DefaultHasher::new();
    (!seed).hash(&mut hasher);
    key.hash(&mut hasher);
    hasher.finish() as usize
}

/// A hash map backed by a minimal perfect hash function.
///
/// Provides O(1) lookup with no collision handling. More space-efficient
/// than `std::collections::HashMap` for large, fixed key sets because
/// it doesn't need to store hash buckets or handle collisions.
///
/// # Example
///
/// ```
/// use perfect_hash::PerfectHashMap;
/// let map = PerfectHashMap::new(vec![
///     ("apple", 1),
///     ("banana", 2),
///     ("cherry", 3),
/// ]);
/// assert_eq!(map.get(&"banana"), Some(&2));
/// assert_eq!(map.get(&"grape"), None);
/// ```
#[derive(Debug)]
pub struct PerfectHashMap<K, V> {
    keys: Vec<K>,
    values: Vec<V>,
    seed: u64,
}

impl<K: Hash + Eq + Clone, V> PerfectHashMap<K, V> {
    /// Build a perfect hash map from a vector of key-value pairs.
    pub fn new(pairs: Vec<(K, V)>) -> Self {
        let n = pairs.len();
        let original_keys: Vec<K> = pairs.iter().map(|(k, _)| k.clone()).collect();
        let original_values: Vec<V> = pairs.into_iter().map(|(_, v)| v).collect();

        let mph = MinimalPerfectHash::new(original_keys.clone());
        let seed = mph.seed;

        let mut keys_by_slot: Vec<Option<K>> = (0..n).map(|_| None).collect();
        let mut values_by_slot: Vec<Option<V>> = (0..n).map(|_| None).collect();
        for (key_idx, key) in original_keys.iter().enumerate() {
            let slot = mph.get_index(key).expect("Key should be in MPH");
            keys_by_slot[slot] = Some(key.clone());
            values_by_slot[slot] = Some(original_values[key_idx].clone());
        }

        PerfectHashMap {
            keys: keys_by_slot.into_iter().map(|x| x.unwrap()).collect(),
            values: values_by_slot.into_iter().map(|x| x.unwrap()).collect(),
            seed,
        }
    }

    /// Get the value for a key.
    #[inline]
    pub fn get(&self, key: &K) -> Option<&V> {
        let n = self.keys.len();
        let h1 = hash1(key, self.seed) % n;
        let h2 = hash2(key, self.seed) % n;

        if self.keys[h1] == *key {
            Some(&self.values[h1])
        } else if self.keys[h2] == *key {
            Some(&self.values[h2])
        } else {
            None
        }
    }

    /// Returns the number of key-value pairs.
    pub fn len(&self) -> usize {
        self.keys.len()
    }

    /// Returns true if the map is empty.
    pub fn is_empty(&self) -> bool {
        self.keys.is_empty()
    }
}

