# XXH128 — A 128-bit Hash Function

Below is a self-contained implementation of **XXH128**, the 128-bit variant of xxHash by Yann Collet. It's one of the best non-cryptographic hashes available: extremely fast (often >10 GB/s), excellent avalanche, and very low collision rates in practice. It's the standard choice for hash tables, deduplication, checksumming, and similar tasks.

## The Code

```c
/*
 * xxHash XXH128 - 128-bit non-cryptographic hash function
 *
 * Self-contained reference implementation based on xxHash v0.8.0
 * by Yann Collet. Licensed under BSD 2-Clause License.
 * https://github.com/Cyan4973/xxHash
 *
 * Compile: gcc -O2 -o xxh128_demo xxh128.c
 */

#include <stdio.h>
#include <stddef.h>
#include <stdint.h>
#include <string.h>

/* =============================================================
 * 1. Constants
 *
 * Large odd primes chosen so that multiplication by them acts
 * as a strong bit-mixing operation. They are coprime with 2^64
 * and their bit patterns don't align with simple powers of two.
 * ============================================================= */

static const uint64_t XXH_PRIME64_1 = 0x9E3779B185EBCA87ULL;
static const uint64_t XXH_PRIME64_2 = 0x14DEF9DEA2F79CD65ULL;
static const uint64_t XXH_PRIME64_3 = 0x165667B19E3779F9ULL;
static const uint64_t XXH_PRIME64_4 = 0x85EBCA77C2B2AE63ULL;
static const uint64_t XXH_PRIME64_5 = 0x27D4EB2F165667C5ULL;

/* =============================================================
 * 2. Basic primitives
 * ============================================================= */

static inline uint64_t xxh_rotl64(uint64_t x, int r) {
    return (x << r) | (x >> (64 - r));
}

static inline uint64_t xxh_get64(const void* p) {
    uint64_t v; memcpy(&v, p, sizeof(v)); return v;
}

static inline uint32_t xxh_get32(const void* p) {
    uint32_t v; memcpy(&v, p, sizeof(v)); return v;
}

/* =============================================================
 * 3. XXH64 building blocks
 *
 * xxh64_round is the workhorse: multiply by a prime, rotate to
 * spread bits across all 64 bit positions, multiply by another
 * prime. This is what gives xxHash its excellent avalanche.
 *
 * xxh64_merge_round folds an accumulator back into a running
 * hash. The XOR + multiply-by-prime combination ensures small
 * changes in the accumulator produce large changes in the hash.
 *
 * xxh64_avalanche is the final mixing step: three rounds of
 * XOR-shift-multiply so every output bit depends on every input
 * bit.
 * ============================================================= */

static inline uint64_t xxh64_round(uint64_t acc, uint64_t input) {
    acc += input * XXH_PRIME64_2;
    acc  = xxh_rotl64(acc, 31);
    acc *= XXH_PRIME64_1;
    return acc;
}

static inline uint64_t xxh64_merge_round(uint64_t acc, uint64_t val) {
    val  = xxh64_round(0, val);
    acc ^= val;
    acc  = acc * XXH_PRIME64_1 + XXH_PRIME64_4;
    return acc;
}

static inline uint64_t xxh64_avalanche(uint64_t h) {
    h ^= h >> 33;
    h *= XXH_PRIME64_2;
    h ^= h >> 29;
    h *= XXH_PRIME64_3;
    h ^= h >> 32;
    return h;
}

/* =============================================================
 * 4. Result type
 * ============================================================= */

typedef struct {
    uint64_t low64;
    uint64_t high64;
} xxh128_t;

/* =============================================================
 * 5. Finalize: process the 0..31 byte tail, cross-mix the two
 *    64-bit halves, then avalanche each half independently.
 * ============================================================= */

static xxh128_t xxh128_finalize(uint64_t h0, uint64_t h1,
                                const uint8_t* tail, size_t tail_len)
{
    /* Mix tail bytes into both halves */
    while (tail_len >= 8) {
        uint64_t k = xxh64_round(0, xxh_get64(tail));
        h0 ^= k;  h1 ^= k;
        tail     += 8;
        tail_len -= 8;
    }
    if (tail_len >= 4) {
        uint32_t k = xxh_get32(tail);
        h0 ^= k;  h1 ^= k;
        tail     += 4;
        tail_len -= 4;
    }
    while (tail_len > 0) {
        uint8_t k = *tail++;
        h0 ^= k;  h1 ^= k;
        --tail_len;
    }

    /* Cross-half mixing: each half now depends on bits from both */
    h0 ^= h1 >> 32;
    h1 ^= h0 & 0xFFFFFFFFU;
    h0 ^= h1 << 32;
    h1 ^= h0 >> 32;
    h0 ^= h1 & 0xFFFFFFFFU;
    h1 ^= h0 << 32;

    /* Final avalanche on each half */
    return (xxh128_t){ xxh64_avalanche(h0), xxh64_avalanche(h1) };
}

/* =============================================================
 * 6. XXH128 main entry point
 *
 * Algorithm:
 *   a) If len >= 32, process the input in 32-byte stripes.
 *      Each stripe updates 8 independent accumulators (v1..v8),
 *      one 8-byte word per accumulator. This gives instruction-
 *      level parallelism: modern CPUs execute several rounds
 *      concurrently.
 *   b) Combine the 8 accumulators into two 64-bit values (h0, h1)
 *      using rotations and addition, then fold each accumulator
 *      back in via merge_round.
 *   c) Add the length to both halves (so messages of different
 *      lengths can't collide trivially).
 *   d) Process the remaining 0..31 tail bytes.
 *   e) Cross-mix the two halves and avalanche each.
 * ============================================================= */

xxh128_t xxh128(const void* input, size_t len, uint64_t seed) {
    const uint8_t* p   = (const uint8_t*)input;
    const uint8_t* end = p + len;
    uint64_t h0, h1;

    if (len >= 32) {
        const uint8_t* limit = end - 32;

        /* Asymmetric init: v1..v4 and v5..v8 use different prime
         * offsets so the two halves of the final hash are
         * uncorrelated. */
        uint64_t v1 = seed + XXH_PRIME64_1 + XXH_PRIME64_2;
        uint64_t v2 = seed + XXH_PRIME64_2;
        uint64_t v3 = seed + 0;
        uint64_t v4 = seed - XXH_PRIME64_1;
        uint64_t v5 = seed + XXH_PRIME64_3;
        uint64_t v6 = seed + XXH_PRIME64_3 + XXH_PRIME64_2;
        uint64_t v7 = seed + XXH_PRIME64_3 + XXH_PRIME64_2 + XXH_PRIME64_1;
        uint64_t v8 = seed + XXH_PRIME64_3 + XXH_PRIME64_2 + XXH_PRIME64_1 + XXH_PRIME64_2;

        do {
            v1 = xxh64_round(v1, xxh_get64(p)); p += 8;
            v2 = xxh64_round(v2, xxh_get64(p)); p += 8;
            v3 = xxh64_round(v3, xxh_get64(p)); p += 8;
            v4 = xxh64_round(v4, xxh_get64(p)); p += 8;
            v5 = xxh64_round(v5, xxh_get64(p)); p += 8;
            v6 = xxh64_round(v6, xxh_get64(p)); p += 8;
            v7 = xxh64_round(v7, xxh_get64(p)); p += 8;
            v8 = xxh64_round(v8, xxh_get64(p)); p += 8;
        } while (p <= limit);

        /* Combine accumulators into two 64-bit values */
        h0 = xxh_rotl64(v1, 1)  + xxh_rotl64(v2, 7)
           + xxh_rotl64(v3, 12) + xxh_rotl64(v4, 18);
        h1 = xxh_rotl64(v5, 1)  + xxh_rotl64(v6, 7)
           + xxh_rotl64(v7, 12) + xxh_rotl64(v8, 18);

        /* Fold each accumulator back in (last two are cross-folds) */
        h0 ^= xxh64_merge_round(h0, v1);
        h1 ^= xxh64_merge_round(h1, v5);
        h0 ^= xxh64_merge_round(h0, v2);
        h1 ^= xxh64_merge_round(h1, v6);
        h0 ^= xxh64_merge_round(h0, v3);
        h1 ^= xxh64_merge_round(h1, v7);
        h0 ^= xxh64_merge_round(h1, v4);   /* cross-fold */
        h1 ^= xxh64_merge_round(h0, v8);   /* cross-fold */
    } else {
        /* Short input: different initialization */
        h0 = seed + XXH_PRIME64_3 + XXH_PRIME64_4;
        h1 = seed + XXH_PRIME64_4;
    }

    /* Incorporate length so different-length messages can't collide */
    h0 += (uint64_t)len;
    h1 += (uint64_t)len;

    return xxh128_finalize(h0, h1, end - (len & 31), len & 31);
}

/* =============================================================
 * 7. Demo / sanity check
 * ============================================================= */

static void print_hex(const xxh128_t* h) {
    printf("%016llx%016llx",
           (unsigned long long)h->high64,
           (unsigned long long)h->low64);
}

int main(void) {
    printf("XXH128 demo (seed = 0)\n");
    printf("=======================\n\n");

    const char* inputs[] = {
        "",
        "a",
        "abc",
