void simd_sort_register(V& v) {
    // Odd-even transposition (batcher-style) within one SIMD register.
    // For width N, log2(N) stages of compare-exchange with stride 1, 2, 4, ...
    constexpr int N = V::size();
    for (int stride = 1; stride < N; stride <<= 1) {
        // Compare-exchange adjacent pairs
        V lo = stdx::shuffle(v, v, [](auto i) { return i ^ 1; });
        V hi = stdx::max(v, lo);
        V lo2 = stdx::min(v, lo);
        v = stdx::merge(lo2, hi);  // interleave back
        // ... (full Batcher network omitted for brevity)
    }
}

int main() {
    using V = stdx::native_simd<float>;
    std::vector<float> data = {5.f, 2.f, 8.f, 1.f, 9.f, 3.f, 7.f, 4.f};

    alignas(V::alignment()) float buf[V::size()];
    for (size_t i = 0; i < V::size(); ++i) buf[i] = data[i];

    V v(buf, stdx::element_aligned);
    // simd_sort_register(v);  // would sort in-register
    // v.copy_to(buf, stdx::element_aligned);

    for (float f : buf) std::cout << f << ' ';
    std::cout << '\n';
}
```

I left the Batcher network incomplete on purpose — getting it right is finicky and not the point. The point is: **this is what "SIMD sort" looks like today**, and it's a lot of code.

